                   // so we overwrite the default one\n  new chipyard.config.WithUniformBusFrequencies(2) ++               // configured to be as fast as possible\n  new chipyard.config.AbstractConfig)\n\n// No L2 and a ludicrous L1D\nclass SpikeUltraFastConfig extends Config(\n  new testchipip.soc.WithNoScratchpads ++\n  new chipyard.WithSpikeTCM ++\n  new chipyard.config.WithBroadcastManager ++\n  new SpikeFastUARTConfig)\n\nclass dmiSpikeUltraFastConfig extends Config(\n  new chipyard.harness.WithSerialTLTiedOff ++                    // don't attach anything to serial-tilelink\n  new chipyard.config.WithDMIDTM ++                              // have debug module expose a clocked DMI port\n  new SpikeUltraFastConfig)\n\nclass dmiCheckpointingSpikeUltraFastConfig extends Config(\n  new chipyard.config.WithNPMPs(0) ++                            // remove PMPs (reduce non-core arch state)\n  new dmiSpikeUltraFastConfig)\n\n// Add the default firechip devices\nclass SpikeUltraFastDevicesConfig extends Config(\n  new chipyard.harness.WithSimBlockDevice ++\n  new chipyard.harness.WithLoopbackNIC ++\n  new icenet.WithIceNIC ++\n  new testchipip.iceblk.WithBlockDevice ++\n  new SpikeUltraFastConfig)\n","chipyard:generators/chipyard/src/main/scala/config/TracegenConfigs.scala":"package chipyard\n\nimport org.chipsalliance.cde.config.{Config}\nimport freechips.rocketchip.rocket.{DCacheParams}\n\nclass AbstractTraceGenConfig extends Config(\n  new chipyard.harness.WithAbsoluteFreqHarnessClockInstantiator ++\n  new chipyard.harness.WithBlackBoxSimMem ++\n  new chipyard.harness.WithTraceGenSuccess ++\n  new chipyard.harness.WithClockFromHarness ++\n  new chipyard.harness.WithResetFromHarness ++\n  new chipyard.iobinders.WithAXI4MemPunchthrough ++\n  new chipyard.iobinders.WithTraceGenSuccessPunchthrough ++\n  new chipyard.clocking.WithPassthroughClockGenerator ++\n  new chipyard.clocking.WithClockGroupsCombinedByName((\"uncore\", Seq(\"sbus\"), Nil)) ++\n  new chipyard.config.WithTracegenSystem ++\n  new chipyard.config.WithNoSubsystemClockIO ++\n  new chipyard.config.WithUniformBusFrequencies(1000.0) ++\n  new freechips.rocketchip.subsystem.WithCoherentBusTopology ++\n  new freechips.rocketchip.groundtest.GroundTestBaseConfig)\n\n\n\nclass TraceGenConfig extends Config(\n  new tracegen.WithTraceGen()(List.fill(2) { DCacheParams(nMSHRs = 0, nSets = 16, nWays = 2) }) ++\n  new AbstractTraceGenConfig)\n\nclass NonBlockingTraceGenConfig extends Config(\n  new tracegen.WithTraceGen()(List.fill(2) { DCacheParams(nMSHRs = 2, nSets = 16, nWays = 2) }) ++\n  new AbstractTraceGenConfig)\n\nclass BoomV3TraceGenConfig extends Config(\n  new tracegen.WithBoomV3TraceGen()(List.fill(2) { DCacheParams(nMSHRs = 8, nSets = 16, nWays = 2) }) ++\n  new freechips.rocketchip.subsystem.WithInclusiveCache ++\n  new AbstractTraceGenConfig)\n\nclass BoomV4TraceGenConfig extends Config(\n  new tracegen.WithBoomV4TraceGen()(List.fill(2) { DCacheParams(nMSHRs = 8, nSets = 16, nWays = 2) }) ++\n  new freechips.rocketchip.subsystem.WithInclusiveCache ++\n  new AbstractTraceGenConfig)\n\nclass NonBlockingTraceGenL2Config extends Config(\n  new tracegen.WithL2TraceGen()(List.fill(2)(DCacheParams(nMSHRs = 2, nSets = 16, nWays = 4))) ++\n  new freechips.rocketchip.subsystem.WithInclusiveCache ++\n  new AbstractTraceGenConfig)\n\nclass NonBlockingTraceGenL2RingConfig extends Config(\n  new tracegen.WithL2TraceGen()(List.fill(2)(DCacheParams(nMSHRs = 2, nSets = 16, nWays = 4))) ++\n  new testchipip.soc.WithRingSystemBus ++\n  new freechips.rocketchip.subsystem.WithInclusiveCache ++\n  new AbstractTraceGenConfig)\n","chipyard:generators/chipyard/src/main/scala/config/TutorialConfigs.scala":"package chipyard\n\nimport org.chipsalliance.cde.config.{Config}\nimport constellation.channel._\nimport constellation.routing._\nimport constellation.topology._\nimport constellation.noc._\nimport constellation.soc.{GlobalNoCParams}\nimport scala.collection.immutable.ListMap\n\n// This file is designed to accompany a live tutorial, with slides.\n// For each of 4 phases, participants will customize and build a\n// small demonstration config.\n\n// This file was originally developed for the cancelled ASPLOS-2020\n// Chipyard tutorial. While the configs here work, the corresponding\n// slideware has not yet been created.\n\n// NOTE: Configs should be read bottom-up, since they are applied bottom-up\n\n// NOTE: The TutorialConfigs build off of the AbstractConfig defined in AbstractConfig.scala\n//       Users should try to understand the functionality of the AbstractConfig before proceeding\n//       with the TutorialConfigs below\n\n// Tutorial Phase 1: Configure the cores, caches\nclass TutorialStarterConfig extends Config(\n  // CUSTOMIZE THE CORE\n  // Uncomment out one (or multiple) of the lines below, and choose\n  // how many cores you want.\n  // new freechips.rocketchip.rocket.WithNHugeCores(1) ++    // Specify we want some number of Rocket cores\n  // new boom.v3.common.WithNSmallBooms(1) ++                     // Specify we want some number of BOOM cores\n\n  // CUSTOMIZE the L2\n  // Uncomment this line, and specify a size if you want to have a L2\n  // new freechips.rocketchip.subsystem.WithInclusiveCache(nBanks=1, nWays=4, capacityKB=128) ++\n\n  new chipyard.config.AbstractConfig\n)\n\n// Tutorial Phase 2: Integrate a TileLink or AXI4 MMIO device\nclass TutorialMMIOConfig extends Config(\n\n  // Attach either a TileLink or AXI4 version of GCD\n  // Uncomment one of the below lines\n  // new chipyard.example.WithGCD(useAXI4=false) ++ // Use TileLink version\n  // new chipyard.example.WithGCD(useAXI4=true) ++  // Use AXI4 version\n\n  // For this demonstration we assume the base system is a single-core Rocket, for fast elaboration\n  new freechips.rocketchip.rocket.WithNHugeCores(1) ++\n  new chipyard.config.AbstractConfig\n)\n\n\n// Tutorial Phase 5: Map a multicore heterogeneous SoC with multiple cores and memory-mapped accelerators\nclass TutorialNoCConfig extends Config(\n  new chipyard.harness.WithDontTouchChipTopPorts(false) ++\n  // Try changing the dimensions of the Mesh topology\n  new constellation.soc.WithGlobalNoC(constellation.soc.GlobalNoCParams(\n    NoCParams(\n      topology        = TerminalRouter(Mesh2D(3, 4)),\n      channelParamGen = (a, b) => UserChannelParams(Seq.fill(12) { UserVirtualChannelParams(4) }),\n      routingRelation = NonblockingVirtualSubnetworksRouting(TerminalRouterRouting(\n        Mesh2DEscapeRouting()), 10, 1)\n    )\n  )) ++\n  // The inNodeMapping and outNodeMapping values are the physical identifiers of\n  // routers on the topology to map the agents to. Try changing these to any\n  // value within the range [0, topology.nNodes)\n  new constellation.soc.WithPbusNoC(constellation.protocol.GlobalTLNoCParams(\n    constellation.protocol.DiplomaticNetworkNodeMapping(\n      inNodeMapping = ListMap(\"Core\" -> 7),\n      outNodeMapping = ListMap(\n        \"pbus\" -> 8, \"uart\" -> 9, \"control\" -> 10, \"gcd\" -> 11,\n        \"writeQueue[0]\" -> 0, \"writeQueue[1]\" -> 1, \"tailChain[0]\" -> 2))\n  )) ++\n  new constellation.soc.WithSbusNoC(constellation.protocol.GlobalTLNoCParams(\n    constellation.protocol.DiplomaticNetworkNodeMapping(\n      inNodeMapping = ListMap(\n        \"Core 0\" -> 0, \"Core 1\" -> 1,\n        \"serial-tl\" -> 2),\n      outNodeMapping = ListMap(\n        \"system[0]\" -> 3, \"system[1]\" -> 4, \"system[2]\" -> 5, \"system[3]\" -> 6,\n        \"pbus\" -> 7))\n  )) ++\n  new chipyard.example.WithGCD ++\n  new chipyard.harness.WithLoopbackNIC ++\n  new icenet.WithIceNIC ++\n  new fftgenerator.WithFFTGenerator(numPoints=8) ++\n  new chipyard.example.WithStreamingFIR ++\n  new chipyard.example.WithStreamingPassthrough ++\n\n  new freechips.rocketchip.subsystem.WithNBanks(4) ++\n  new freechips.rocketchip.rocket.WithNHugeCores(2) ++\n  new chipyard.config.AbstractConfig\n)\n","chipyard:generators/chipyard/src/main/scala/config/VexiiRiscvConfigs.scala":"package chipyard\n\nimport chisel3._\n\nimport org.chipsalliance.cde.config.{Config}\n\n// ---------------------\n// VexiiRiscv Configs\n// ---------------------\n\nclass VexiiRiscvConfig extends Config(\n  new vexiiriscv.WithNVexiiRiscvCores(1) ++\n  new chipyard.config.AbstractConfig)\n","chipyard:generators/chipyard/src/main/scala/config/fragments/ClockingFragments.scala":"package chipyard.config\n\nimport scala.util.matching.Regex\nimport chisel3._\nimport chisel3.util.{log2Up}\n\nimport org.chipsalliance.cde.config.{Field, Parameters, Config}\nimport freechips.rocketchip.subsystem._\nimport freechips.rocketchip.prci._\nimport freechips.rocketchip.diplomacy._\nimport freechips.rocketchip.util.{Symmetric}\nimport freechips.rocketchip.tilelink.{HasTLBusParams}\n\nimport chipyard._\nimport chipyard.clocking._\nimport testchipip.soc.{OffchipBusKey}\n\n// The default RocketChip BaseSubsystem drives its diplomatic clock graph\n// with the implicit clocks of Subsystem. Don't do that, instead we extend\n// the diplomacy graph upwards into the ChipTop, where we connect it to\n// our clock drivers\nclass WithNoSubsystemClockIO extends Config((site, here, up) => {\n  case SubsystemDriveClockGroupsFromIO => false\n})\n\n/**\n  * Mixins to define either a specific tile frequency for a single hart or all harts\n  *\n  * @param fMHz Frequency in MHz of the tile or all tiles\n  * @param hartId Optional hartid to assign the frequency to (if unspecified default to all harts)\n  */\nclass WithTileFrequency(fMHz: Double, hartId: Option[Int] = None) extends ClockNameContainsAssignment({\n    hartId match {\n      case Some(id) => s\"tile_$id\"\n      case None => \"tile\"\n    }\n  },\n  fMHz)\n\nclass BusFrequencyAssignment[T <: HasTLBusParams](re: Regex, key: Field[T]) extends Config((site, here, up) => {\n  case ClockFrequencyAssignersKey => up(ClockFrequencyAssignersKey, site) ++\n    Seq((cName: String) => site(key).dtsFrequency.flatMap { f =>\n      re.findFirstIn(cName).map {_ => (f.toDouble / (1000 * 1000)) }\n    })\n})\n\n/**\n  * Provides a diplomatic frequency for all clock sinks with an unspecified\n  * frequency bound to each bus.\n  *\n  * For example, the L2 cache, when bound to the sbus, receives a separate\n  * clock that appears as \"subsystem_sbus_<num>\".  This fragment ensures that\n  * clock requests the same frequency as the sbus itself.\n  */\n\nclass WithInheritBusFrequencyAssignments extends Config(\n  new BusFrequencyAssignment(\"subsystem_sbus_\\\\d+\".r, SystemBusKey) ++\n  new BusFrequencyAssignment(\"subsystem_pbus_\\\\d+\".r, PeripheryBusKey) ++\n  new BusFrequencyAssignment(\"subsystem_cbus_\\\\d+\".r, ControlBusKey) ++\n  new BusFrequencyAssignment(\"subsystem_fbus_\\\\d+\".r, FrontBusKey) ++\n  new BusFrequencyAssignment(\"subsystem_mbus_\\\\d+\".r, MemoryBusKey)\n)\n\n/**\n  * Mixins to specify crossing types between the 5 traditional TL buses\n  *\n  * Note: these presuppose the legacy connections between buses and set\n  * parameters in SubsystemCrossingParams; they may not be resuable in custom\n  * topologies (but you can specify the desired crossings in your topology).\n  *\n  * @param xType The clock crossing type\n  *\n  */\n\nclass WithSbusToMbusCrossingType(xType: ClockCrossingType) extends Config((site, here, up) => {\n    case SbusToMbusXTypeKey => xType\n})\nclass WithSbusToCbusCrossingType(xType: ClockCrossingType) extends Config((site, here, up) => {\n    case SbusToCbusXTypeKey => xType\n})\nclass WithCbusToPbusCrossingType(xType: ClockCrossingType) extends Config((site, here, up) => {\n    case CbusToPbusXTypeKey => xType\n})\nclass WithFbusToSbusCrossingType(xType: ClockCrossingType) extends Config((site, here, up) => {\n    case FbusToSbusXTypeKey => xType\n})\n\n/**\n  * Mixins to set the dtsFrequency field of BusParams -- these will percolate its way\n  * up the diplomatic graph to the clock sources.\n  */\nclass WithPeripheryBusFrequency(freqMHz: Double) extends Config(\n  new freechips.rocketchip.subsystem.WithTimebase((freqMHz * 1e3).toLong) ++ // Match DTS timebase to PBUS (i.e. RTC) frequency. Makes RTC 'tick' at the PBUS rate.\n  new Config((site, here, up) => {\n    case PeripheryBusKey => up(PeripheryBusKey, site).copy(dtsFrequency = Some(BigInt((freqMHz * 1e6).toLong)))\n  })\n)\nclass WithMemoryBusFrequency(freqMHz: Double) extends Config((site, here, up) => {\n  case MemoryBusKey => up(MemoryBusKey, site).copy(dtsFrequency = Some(BigInt((freqMHz * 1e6).toLong)))\n})\nclass WithSystemBusFrequency(freqMHz: Double) extends Config((site, here, up) => {\n  case SystemBusKey => up(SystemBusKey, site).copy(dtsFrequency = Some(BigInt((freqMHz * 1e6).toLong)))\n})\nclass WithFrontBusFrequency(freqMHz: Double) extends Config((site, here, up) => {\n  case FrontBusKey => up(FrontBusKey, site).copy(dtsFrequency = Some(BigInt((freqMHz * 1e6).toLong)))\n})\nclass WithControlBusFrequency(freqMHz: Double) extends Config((site, here, up) => {\n  case ControlBusKey => up(ControlBusKey, site).copy(dtsFrequency = Some(BigInt((freqMHz * 1e6).toLong)))\n})\nclass WithOffchipBusFrequency(freqMHz: Double) extends Config((site, here, up) => {\n  case OffchipBusKey => up(OffchipBusKey, site).copy(dtsFrequency = Some(BigInt((freqMHz * 1e6).toLong)))\n})\nclass WithUniformBusFrequencies(freqMHz: Double) extends Config(\n  new WithPeripheryBusFrequency(freqMHz) ++\n  new WithSystemBusFrequency(freqMHz) ++\n  new WithFrontBusFrequency(freqMHz) ++\n  new WithControlBusFrequency(freqMHz) ++\n  new WithOffchipBusFrequency(freqMHz) ++\n  new WithMemoryBusFrequency(freqMHz)\n)\n\nclass WithRationalMemoryBusCrossing extends WithSbusToMbusCrossingType(RationalCrossing(Symmetric))\nclass WithAsynchrousMemoryBusCrossing extends WithSbusToMbusCrossingType(AsynchronousCrossing())\n\n// Remove the tile clock gaters in this system\nclass WithNoTileClockGaters extends Config((site, here, up) => {\n  case ChipyardPRCIControlKey => up(ChipyardPRCIControlKey).copy(enableTileClockGating = false)\n})\n\n// Remove the tile reset control blocks in this system\nclass WithNoTileResetSetters extends Config((site, here, up) => {\n  case ChipyardPRCIControlKey => up(ChipyardPRCIControlKey).copy(enableTileResetSetting = false)\n})\n\n// Remove the global reset synchronizers in this system\nclass WithNoResetSynchronizers extends Config((site, here, up) => {\n  case ChipyardPRCIControlKey => up(ChipyardPRCIControlKey).copy(enableResetSynchronizers = false)\n})\n\n// Remove any ClockTap ports in this system\nclass WithNoClockTap extends Config((site, here, up) => {\n  case ClockTapKey => false\n})\n","chipyard:generators/chipyard/src/main/scala/config/fragments/PeripheralFragments.scala":"package chipyard.config\n\nimport scala.util.matching.Regex\nimport chisel3._\nimport chisel3.util.{log2Up}\n\nimport org.chipsalliance.cde.config.{Config}\nimport freechips.rocketchip.devices.tilelink.{BootROMLocated, PLICKey, CLINTKey}\nimport freechips.rocketchip.devices.debug.{Debug, ExportDebug, DebugModuleKey, DMI, JtagDTMKey, JtagDTMConfig}\nimport freechips.rocketchip.prci.{AsynchronousCrossing}\nimport chipyard.stage.phases.TargetDirKey\nimport freechips.rocketchip.subsystem._\n\nimport sifive.blocks.devices.gpio._\nimport sifive.blocks.devices.uart._\nimport sifive.blocks.devices.spi._\nimport sifive.blocks.devices.i2c._\nimport sifive.blocks.devices.timer._\n\nimport testchipip._\n\nimport chipyard.{ExtTLMem}\n\n/**\n  * Config fragment for adding a BootROM to the SoC\n  *\n  * @param address the address of the BootROM device\n  * @param size the size of the BootROM\n  * @param hang the power-on reset vector, i.e. the program counter will be set to this value on reset\n  * @param contentFileName the path to the BootROM image\n  */\nclass WithBootROM(address: BigInt = 0x10000, size: Int = 0x10000, hang: BigInt = 0x10000) extends Config((site, here, up) => {\n  case BootROMLocated(x) => up(BootROMLocated(x), site)\n      .map(_.copy(\n        address = address,\n        size = size,\n        hang = hang,\n        contentFileName = s\"${site(TargetDirKey)}/bootrom.rv${site(MaxXLen)}.img\"\n      ))\n})\n\n// DOC include start: gpio config fragment\n/**\n * Config fragment for adding a GPIO peripheral device to the SoC\n *\n * @param address the address of the GPIO device\n * @param width the number of pins of the GPIO device\n */\nclass WithGPIO(address: BigInt = 0x10010000, width: Int = 4) extends Config ((site, here, up) => {\n  case PeripheryGPIOKey => up(PeripheryGPIOKey) ++ Seq(\n    GPIOParams(address = address, width = width, includeIOF = false))\n})\n// DOC include end: gpio config fragment\n\n/**\n * Config fragment for removing all UART peripheral devices from the SoC\n */\nclass WithNoUART extends Config((site, here, up) => {\n  case PeripheryUARTKey => Nil\n})\n\n/**\n  * Config fragment for adding a UART peripheral device to the SoC\n  *\n  * @param address the address of the UART device\n  * @param baudrate the baudrate of the UART device\n  */\nclass WithUART(baudrate: BigInt = 115200, address: BigInt = 0x10020000, txEntries: Int = 8, rxEntries: Int = 8) extends Config ((site, here, up) => {\n  case PeripheryUARTKey => up(PeripheryUARTKey) ++ Seq(\n    UARTParams(address = address, nTxEntries = txEntries, nRxEntries = rxEntries, initBaudRate = baudrate))\n})\n\n// @deprecated(\"Use WithUART instead of WithUARTFIFOEntries\", \"chipyard v1.10\")\nclass WithUARTFIFOEntries(txEntries: Int, rxEntries: Int) extends Config((site, here, up) => {\n  case PeripheryUARTKey => up(PeripheryUARTKey).map(_.copy(nTxEntries = txEntries, nRxEntries = rxEntries))\n})\n\nclass WithUARTInitBaudRate(baudrate: BigInt = 115200) extends Config ((site, here, up) => {\n  case PeripheryUARTKey => up(PeripheryUARTKey).map(_.copy(initBaudRate=baudrate))\n})\n\n/**\n  * Config fragment for adding a SPI peripheral device with Execute-in-Place capability to the SoC\n  *\n  * @param address the address of the SPI controller\n  * @param fAddress the address of the Execute-in-Place (XIP) region of the SPI flash memory\n  * @param size the size of the Execute-in-Place (XIP) region of the SPI flash memory\n  */\nclass WithSPIFlash(size: BigInt = 0x10000000, address: BigInt = 0x10030000, fAddress: BigInt = 0x20000000) extends Config((site, here, up) => {\n  // Note: the default size matches freedom with the addresses below\n  case PeripherySPIFlashKey => up(PeripherySPIFlashKey) ++ Seq(\n    SPIFlashParams(rAddress = address, fAddress = fAddress, fSize = size))\n})\n\n/**\n  * Config fragment for adding a SPI peripheral device to the SoC\n  *\n  * @param address the address of the SPI controller\n  */\nclass WithSPI(address: BigInt = 0x10031000) extends Config((site, here, up) => {\n  case PeripherySPIKey => up(PeripherySPIKey) ++ Seq(\n    SPIParams(rAddress = address))\n})\n\n/**\n  * Config fragment for adding a I2C peripheral device to the SoC\n  *\n  * @param address the address of the I2C controller\n  */\nclass WithI2C(address: BigInt = 0x10040000) extends Config((site, here, up) => {\n  case PeripheryI2CKey => up(PeripheryI2CKey) ++ Seq(\n    I2CParams(address = address, controlXType = AsynchronousCrossing(), intXType = AsynchronousCrossing())\n  )\n})\n\nclass WithNoDebug extends Config((site, here, up) => {\n  case DebugModuleKey => None\n})\n\nclass WithDMIDTM extends Config((site, here, up) => {\n  case ExportDebug => up(ExportDebug, site).copy(protocols = Set(DMI))\n})\n\n/**\n  * Config fragment for adding a JTAG Debug Module to the SoC\n  *\n  * @param idcodeVersion the version of the JTAG protocol the Debug Module supports\n  * @param partNum the part number of the Debug Module\n  * @param manufId the 11-bit JEDEC Designer ID of the chip manufacturer\n  * @param debugIdleCycles the number of cycles the Debug Module waits before responding to a request\n  */\nclass WithJTAGDTMKey(idcodeVersion: Int = 2, partNum: Int = 0x000, manufId: Int = 0x489, debugIdleCycles: Int = 5) extends Config((site, here, up) => {\n  case JtagDTMKey => new JtagDTMConfig (\n    idcodeVersion = idcodeVersion,\n    idcodePartNum = partNum,\n    idcodeManufId = manufId,\n    debugIdleCycles = debugIdleCycles)\n})\n\nclass WithTLBackingMemory extends Config((site, here, up) => {\n  case ExtMem => None // disable AXI backing memory\n  case ExtTLMem => up(ExtMem, site) // enable TL backing memory\n})\n\nclass WithExtMemIdBits(n: Int) extends Config((site, here, up) => {\n  case ExtMem => up(ExtMem, site).map(x => x.copy(master = x.master.copy(idBits = n)))\n})\n\nclass WithNoPLIC extends Config((site, here, up) => {\n  case PLICKey => None\n})\n\nclass WithDebugModuleAbstractDataWords(words: Int = 16) extends Config((site, here, up) => {\n  case DebugModuleKey => up(DebugModuleKey).map(_.copy(nAbstractDataWords=words))\n})\n\nclass WithNoCLINT extends Config((site, here, up) => {\n  case CLINTKey => None\n})\n\nclass WithNoBootROM extends Config((site, here, up) => {\n  case BootROMLocated(_) => None\n})\n\nclass WithNoBusErrorDevices extends Config((site, here, up) => {\n  case SystemBusKey => up(SystemBusKey).copy(errorDevice = None)\n  case ControlBusKey => up(ControlBusKey).copy(errorDevice = None)\n  case PeripheryBusKey => up(PeripheryBusKey).copy(errorDevice = None)\n  case MemoryBusKey => up(MemoryBusKey).copy(errorDevice = None)\n  case FrontBusKey => up(FrontBusKey).copy(errorDevice = None)\n})\n\nclass WithPeripheryTimer(timerParams: TimerParams = TimerParams(0x4000)) extends Config((site, here, up) => {\n  case PeripheryTimerKey => Seq(timerParams)\n})\n","chipyard:generators/chipyard/src/main/scala/config/fragments/RoCCFragments.scala":"package chipyard.config\n\nimport chisel3._\n\nimport org.chipsalliance.cde.config.{Field, Parameters, Config}\nimport freechips.rocketchip.tile._\nimport freechips.rocketchip.diplomacy._\n\nimport gemmini._\n\nimport chipyard.{TestSuitesKey, TestSuiteHelper}\n\n/**\n * Map from a tileId to a particular RoCC accelerator\n */\ncase object MultiRoCCKey extends Field[Map[Int, Seq[Parameters => LazyRoCC]]](Map.empty[Int, Seq[Parameters => LazyRoCC]])\n\n/**\n * Config fragment to enable different RoCCs based on the tileId\n */\nclass WithMultiRoCC extends Config((site, here, up) => {\n  case BuildRoCC => site(MultiRoCCKey).getOrElse(site(TileKey).tileId, Nil)\n})\n\n/**\n * Assigns what was previously in the BuildRoCC key to specific harts with MultiRoCCKey\n * Must be paired with WithMultiRoCC\n */\nclass WithMultiRoCCFromBuildRoCC(harts: Int*) extends Config((site, here, up) => {\n  case BuildRoCC => Nil\n  case MultiRoCCKey => up(MultiRoCCKey, site) ++ harts.distinct.map { i =>\n    (i -> up(BuildRoCC, site))\n  }\n})\n\nclass WithMultiRoCCGemmini[T <: Data : Arithmetic, U <: Data, V <: Data](\n  harts: Int*)(gemminiConfig: GemminiArrayConfig[T,U,V] = GemminiConfigs.defaultConfig) extends Config((site, here, up) => {\n  case MultiRoCCKey => up(MultiRoCCKey, site) ++ harts.distinct.map { i =>\n    (i -> Seq((p: Parameters) => {\n      implicit val q = p\n      val gemmini = LazyModule(new Gemmini(gemminiConfig))\n      gemmini\n    }))\n  }\n})\n\nclass WithAccumulatorRoCC(op: OpcodeSet = OpcodeSet.custom1) extends Config((site, here, up) => {\n  case BuildRoCC => up(BuildRoCC) ++ Seq((p: Parameters) => {\n    val accumulator = LazyModule(new AccumulatorExample(op, n = 4)(p))\n    accumulator\n  })\n})\n\nclass WithCharacterCountRoCC(op: OpcodeSet = OpcodeSet.custom2) extends Config((site, here, up) => {\n  case BuildRoCC => up(BuildRoCC) ++ Seq((p: Parameters) => {\n    val counter = LazyModule(new CharacterCountExample(op)(p))\n    counter\n  })\n})\n","chipyard:generators/chipyard/src/main/scala/config/fragments/SubsystemFragments.scala":"package chipyard.config\n\nimport org.chipsalliance.cde.config.{Config}\nimport freechips.rocketchip.subsystem._\nimport freechips.rocketchip.resources.{DTSTimebase}\nimport sifive.blocks.inclusivecache.{InclusiveCachePortParameters}\n\n// Replaces the L2 with a broadcast manager for maintaining coherence\nclass WithBroadcastManager extends Config((site, here, up) => {\n  case SubsystemBankedCoherenceKey => up(SubsystemBankedCoherenceKey, site).copy(coherenceManager = CoherenceManagerWrapper.broadcastManager)\n})\n\nclass WithBroadcastParams(params: BroadcastParams) extends Config((site, here, up) => {\n  case BroadcastKey => params\n})\n\nclass WithSystemBusWidth(bitWidth: Int) extends Config((site, here, up) => {\n  case SystemBusKey => up(SystemBusKey, site).copy(beatBytes=bitWidth/8)\n})\n\nclass WithInclusiveCacheWriteBytes(b: Int) extends Config((site, here, up) => {\n  case InclusiveCacheKey => up(InclusiveCacheKey).copy(writeBytes = b)\n})\n\n// Adds buffers on the interior of the inclusive LLC, to improve PD\nclass WithInclusiveCacheInteriorBuffer(buffer: InclusiveCachePortParameters = InclusiveCachePortParameters.full) extends Config((site, here, up) => {\n  case InclusiveCacheKey => up(InclusiveCacheKey).copy(bufInnerInterior=buffer, bufOuterInterior=buffer)\n})\n\n// Adds buffers on the exterior of the inclusive LLC, to improve PD\nclass WithInclusiveCacheExteriorBuffer(buffer: InclusiveCachePortParameters = InclusiveCachePortParameters.full) extends Config((site, here, up) => {\n  case InclusiveCacheKey => up(InclusiveCacheKey).copy(bufInnerExterior=buffer, bufOuterExterior=buffer)\n})\n","chipyard:generators/chipyard/src/main/scala/config/fragments/TileFragments.scala":"package chipyard.config\n\nimport chisel3._\n\nimport org.chipsalliance.cde.config.{Field, Parameters, Config}\nimport freechips.rocketchip.tile._\nimport freechips.rocketchip.subsystem._\nimport freechips.rocketchip.rocket.{RocketCoreParams, MulDivParams, DCacheParams, ICacheParams}\nimport freechips.rocketchip.diplomacy._\n\nimport cva6.{CVA6TileAttachParams}\nimport sodor.common.{SodorTileAttachParams}\nimport ibex.{IbexTileAttachParams}\nimport vexiiriscv.{VexiiRiscvTileAttachParams}\nimport testchipip.cosim.{TracePortKey, TracePortParams}\nimport barf.{TilePrefetchingMasterPortParams}\nimport freechips.rocketchip.trace.{TraceEncoderParams, TraceCoreParams}\nimport tacit.{TacitEncoder}\nimport shuttle.common.{ShuttleTileAttachParams}\nclass WithL2TLBs(entries: Int) extends Config((site, here, up) => {\n  case TilesLocated(InSubsystem) => up(TilesLocated(InSubsystem), site) map {\n    case tp: RocketTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(nL2TLBEntries = entries)))\n    case tp: boom.v3.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(nL2TLBEntries = entries)))\n    case tp: boom.v4.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(nL2TLBEntries = entries)))\n    case other => other\n  }\n})\n\nclass WithTraceIO extends Config((site, here, up) => {\n  case TilesLocated(InSubsystem) => up(TilesLocated(InSubsystem), site) map {\n    case tp: boom.v3.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(trace = true)))\n    case tp: boom.v4.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(trace = true)))\n    case tp: CVA6TileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      trace = true))\n    case other => other\n  }\n  case TracePortKey => Some(TracePortParams())\n})\n\nclass WithNoTraceIO extends Config((site, here, up) => {\n  case TilesLocated(InSubsystem) => up(TilesLocated(InSubsystem), site) map {\n    case tp: boom.v3.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(trace = false)))\n    case tp: boom.v4.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(trace = false)))\n    case tp: CVA6TileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      trace = false))\n    case other => other\n  }\n  case TracePortKey => None\n})\n\nclass WithNPerfCounters(n: Int = 29) extends Config((site, here, up) => {\n  case TilesLocated(InSubsystem) => up(TilesLocated(InSubsystem), site) map {\n    case tp: RocketTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(nPerfCounters = n)))\n    case tp: boom.v3.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(nPerfCounters = n)))\n    case tp: boom.v4.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(nPerfCounters = n)))\n    case other => other\n  }\n})\n\n// Add a Tacit encoder to each tile\nclass WithTacitEncoder extends Config((site, here, up) => {\n   case TilesLocated(InSubsystem) => up(TilesLocated(InSubsystem), site) map {\n     case tp: RocketTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      traceParams = Some(TraceEncoderParams(\n        encoderBaseAddr = 0x3000000 + tp.tileParams.tileId * 0x1000,\n        buildEncoder = (p: Parameters) => LazyModule(new TacitEncoder(new TraceCoreParams(\n          nGroups = 1,\n          xlen = tp.tileParams.core.xLen,\n          iaddrWidth = tp.tileParams.core.xLen\n        ), \n        bufferDepth = 16,\n        coreStages = 5)(p)),\n        useArbiterMonitor = false\n      )),\n      core = tp.tileParams.core.copy(enableTraceCoreIngress=true)))\n    case tp: ShuttleTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      traceParams = Some(TraceEncoderParams(\n        encoderBaseAddr = 0x3000000 + tp.tileParams.tileId * 0x1000,\n        buildEncoder = (p: Parameters) => LazyModule(new TacitEncoder(new TraceCoreParams(\n          nGroups = tp.tileParams.core.retireWidth,\n          xlen = tp.tileParams.core.xLen,\n          iaddrWidth = tp.tileParams.core.xLen\n        ), bufferDepth = 16, coreStages = 7)(p)),\n        useArbiterMonitor = false\n      )),\n      core = tp.tileParams.core.copy(enableTraceCoreIngress=true)))\n   }\n })\n\n// Add a monitor to RTL print the sinked packets into a file for debugging\nclass WithTraceArbiterMonitor extends Config((site, here, up) => {\n  case TilesLocated(InSubsystem) => up(TilesLocated(InSubsystem), site) map {\n    case tp: RocketTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      traceParams = Some(tp.tileParams.traceParams.get.copy(useArbiterMonitor = true))))\n    case tp: ShuttleTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      traceParams = Some(tp.tileParams.traceParams.get.copy(useArbiterMonitor = true))))\n  }\n})\n\nclass WithNPMPs(n: Int = 8) extends Config((site, here, up) => {\n  case TilesLocated(InSubsystem) => up(TilesLocated(InSubsystem), site) map {\n    case tp: RocketTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(nPMPs = n)))\n    case tp: boom.v3.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(nPMPs = n)))\n    case tp: boom.v4.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(nPMPs = n)))\n    case tp: chipyard.SpikeTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      core = tp.tileParams.core.copy(nPMPs = n)))\n    case other => other\n  }\n})\n\n\nclass WithRocketICacheScratchpad extends Config((site, here, up) => {\n  case TilesLocated(InSubsystem) => up(TilesLocated(InSubsystem), site) map {\n    case tp: RocketTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      icache = tp.tileParams.icache.map(_.copy(itimAddr = Some(0x300000 + tp.tileParams.tileId * 0x10000)))\n    ))\n  }\n})\n\nclass WithRocketDCacheScratchpad extends Config((site, here, up) => {\n  case TilesLocated(InSubsystem) => up(TilesLocated(InSubsystem), site) map {\n    case tp: RocketTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(\n      dcache = tp.tileParams.dcache.map(_.copy(nSets = 32, nWays = 1, scratch = Some(0x200000 + tp.tileParams.tileId * 0x10000)))\n    ))\n  }\n})\n\nclass WithTilePrefetchers extends Config((site, here, up) => {\n  case TilesLocated(InSubsystem) => up(TilesLocated(InSubsystem), site) map {\n    case tp: RocketTileAttachParams => tp.copy(crossingParams = tp.crossingParams.copy(\n      master = TilePrefetchingMasterPortParams(tp.tileParams.tileId, tp.crossingParams.master)))\n    case tp: boom.v3.common.BoomTileAttachParams => tp.copy(crossingParams = tp.crossingParams.copy(\n      master = TilePrefetchingMasterPortParams(tp.tileParams.tileId, tp.crossingParams.master)))\n    case tp: boom.v4.common.BoomTileAttachParams => tp.copy(crossingParams = tp.crossingParams.copy(\n      master = TilePrefetchingMasterPortParams(tp.tileParams.tileId, tp.crossingParams.master)))\n    case tp: SodorTileAttachParams => tp.copy(crossingParams = tp.crossingParams.copy(\n      master = TilePrefetchingMasterPortParams(tp.tileParams.tileId, tp.crossingParams.master)))\n    case tp: IbexTileAttachParams => tp.copy(crossingParams = tp.crossingParams.copy(\n      master = TilePrefetchingMasterPortParams(tp.tileParams.tileId, tp.crossingParams.master)))\n    case tp: VexiiRiscvTileAttachParams => tp.copy(crossingParams = tp.crossingParams.copy(\n      master = TilePrefetchingMasterPortParams(tp.tileParams.tileId, tp.crossingParams.master)))\n    case tp: CVA6TileAttachParams => tp.copy(crossingParams = tp.crossingParams.copy(\n      master = TilePrefetchingMasterPortParams(tp.tileParams.tileId, tp.crossingParams.master)))\n  }\n})\n\n// Use SV48\nclass WithSV48 extends Config((site, here, up) => {\n  case TilesLocated(loc) => up(TilesLocated(loc), site) map {\n    case tp: RocketTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(core =\n      tp.tileParams.core.copy(pgLevels = 4)))\n    case tp: boom.v3.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(core =\n      tp.tileParams.core.copy(pgLevels = 4)))\n    case tp: boom.v4.common.BoomTileAttachParams => tp.copy(tileParams = tp.tileParams.copy(core =\n      tp.tileParams.core.copy(pgLevels = 4)))\n  }\n})\n","chipyard:generators/chipyard/src/main/scala/config/fragments/TracegenFragments.scala":"package chipyard.config\n\nimport org.chipsalliance.cde.config.{Config, Field, Parameters}\nimport tracegen.{TraceGenSystem}\nimport chipyard.{BuildSystem}\nimport chipyard.clocking.{HasChipyardPRCI}\n\nclass TraceGenTop(implicit p: Parameters) extends TraceGenSystem\n  with HasChipyardPRCI\n\nclass WithTracegenSystem extends Config((site, here, up) => {\n  case BuildSystem => (p: Parameters) => new TraceGenTop()(p)\n})\n","chipyard:generators/chipyard/src/main/scala/example/CustomChipTop.scala":"package chipyard.example\n\nimport chisel3._\nimport chipyard.iobinders._\n\nimport org.chipsalliance.cde.config._\nimport freechips.rocketchip.diplomacy.{InModuleBody}\nimport freechips.rocketchip.subsystem.{PBUS, HasTileLinkLocations}\nimport chipyard.iocell._\nimport chipyard._\nimport chipyard.harness.{BuildTop}\nimport sifive.blocks.devices.uart._\n\n// A \"custom\" IOCell with additional I/O\n// The IO don't do anything here in this example\nclass CustomDigitalInIOCellBundle extends DigitalInIOCellBundle {\n  val custom_out = Output(Bool())\n  val custom_in = Input(Bool())\n}\n\n// Using a custom digital in iocell instead of the default one\nclass CustomDigitalInIOCell extends RawModule with DigitalInIOCell {\n  val io = IO(new CustomDigitalInIOCellBundle)\n  io.i := io.pad\n  io.custom_out := io.pad\n}\n\ncase class CustomIOCellParams() extends IOCellTypeParams {\n  def analog() = Module(new GenericAnalogIOCell)\n  def gpio() = Module(new GenericDigitalGPIOCell)\n  def input() = Module(new CustomDigitalInIOCell)\n  def output() = Module(new GenericDigitalOutIOCell)\n}\n\nclass CustomChipTop(implicit p: Parameters) extends ChipTop {\n  // making the module name ChipTop instead of CustomChipTop means\n  // we don't have to set the TOP make variable to CustomChipTop\n  override lazy val desiredName = \"ChipTop\"\n\n  // InModuleBody blocks are executed within the LazyModuleImp of this block\n  InModuleBody {\n    iocellMap.foreach { case (interface, cells) => {\n      cells.foreach { _ match {\n        case c: CustomDigitalInIOCell => {\n          c.io.custom_in := false.B\n        }\n        case c: GenericDigitalOutIOCell => {\n          // do nothing\n        }\n        case c => {\n          require(false, \"Unsupported iocell type ${c.getClass}\")\n        }\n      }}\n    }}\n\n    // demonstrate accessing the iocellMap directly\n    val serialTLIOCells = iocellMap(\"interface testchipip.CanHavePeripheryTLSerial\")\n  }\n}\n\nclass WithCustomIOCells extends Config((site, here, up) => {\n  case IOCellKey => CustomIOCellParams()\n})\n\nclass WithCustomChipTop extends Config((site, here, up) => {\n  case BuildTop => (p: Parameters) => new CustomChipTop()(p)\n})\n\nclass WithBrokenOutUARTIO extends OverrideIOBinder({\n  (system: HasPeripheryUART) => {\n    val uart_txd = IO(Output(Bool()))\n    val uart_rxd = IO(Input(Bool()))\n    system.uart(0).rxd := uart_rxd\n    uart_txd := system.uart(0).txd\n    val where = PBUS // TODO fix\n    val bus = system.asInstanceOf[HasTileLinkLocations].locateTLBusWrapper(where)\n    val freqMHz = bus.dtsFrequency.get / 1000000\n    (Seq(UARTPort(() => {\n      val uart_wire = Wire(new UARTPortIO(system.uart(0).c))\n      uart_wire.txd := uart_txd\n      uart_rxd := uart_wire.rxd\n      uart_wire\n    }, 0, freqMHz.toInt)), Nil)\n  }\n})\n","chipyard:generators/chipyard/src/main/scala/example/EmptyChipTop.scala":"package chipyard.example\n\nimport chisel3._\n\nimport org.chipsalliance.cde.config._\nimport freechips.rocketchip.diplomacy._\nimport freechips.rocketchip.util.{DontTouch}\n\nimport chipyard._\nimport chipyard.harness.{BuildTop}\n\nclass EmptyChipTop(implicit p: Parameters) extends LazyModule {\n  override lazy val module = new Impl\n  class Impl extends LazyRawModuleImp(this) with DontTouch {\n    // Your custom non-rocketchip-soc stuff here\n  }\n}\n\nclass WithEmptyChipTop extends Config((site, here, up) => {\n  case BuildTop => (p: Parameters) => new EmptyChipTop()(p)\n})\n","chipyard:generators/chipyard/src/main/scala/example/FlatChipTop.scala":"package chipyard.example\n\n\nimport chisel3._\nimport org.chipsalliance.cde.config.{Config, Field, Parameters}\nimport freechips.rocketchip.diplomacy._\nimport freechips.rocketchip.prci._\nimport freechips.rocketchip.util._\nimport freechips.rocketchip.subsystem.{PBUS, HasTileLinkLocations}\nimport freechips.rocketchip.devices.debug.{ExportDebug, JtagDTMKey, Debug}\nimport freechips.rocketchip.tilelink.{TLBuffer, TLFragmenter}\nimport chipyard.{BuildSystem, DigitalTop}\nimport chipyard.harness.{BuildTop}\nimport chipyard.clocking._\nimport chipyard.iobinders._\nimport chipyard.iocell._\nimport testchipip.serdes.{SerialTLKey}\n\nclass WithFlatChipTop extends Config((site, here, up) => {\n  case BuildTop => (p: Parameters) => new FlatChipTop()(p)\n})\n\n// This \"FlatChipTop\" uses no IOBinders, so all the IO have\n// to be explicitly constructed.\n// This only supports the base \"DigitalTop\"\nclass FlatChipTop(implicit p: Parameters) extends LazyModule with HasChipyardPorts {\n  override lazy val desiredName = \"ChipTop\"\n  val system = LazyModule(p(BuildSystem)(p)).suggestName(\"system\").asInstanceOf[DigitalTop]\n\n  //========================\n  // Diplomatic clock stuff\n  //========================\n  val tlbus = system.locateTLBusWrapper(system.prciParams.slaveWhere)\n  val baseAddress = system.prciParams.baseAddress\n  val clockDivider  = system.prci_ctrl_domain { LazyModule(new TLClockDivider (baseAddress + 0x20000, tlbus.beatBytes)) }\n  val clockSelector = system.prci_ctrl_domain { LazyModule(new TLClockSelector(baseAddress + 0x30000, tlbus.beatBytes)) }\n  val pllCtrl       = system.prci_ctrl_domain { LazyModule(new FakePLLCtrl    (baseAddress + 0x40000, tlbus.beatBytes)) }\n\n  tlbus.coupleTo(\"clock-div-ctrl\") { clockDivider.tlNode := TLFragmenter(tlbus.beatBytes, tlbus.blockBytes) := TLBuffer() := _ }\n  tlbus.coupleTo(\"clock-sel-ctrl\") { clockSelector.tlNode := TLFragmenter(tlbus.beatBytes, tlbus.blockBytes) := TLBuffer() := _ }\n  tlbus.coupleTo(\"pll-ctrl\") { pllCtrl.tlNode := TLFragmenter(tlbus.beatBytes, tlbus.blockBytes) := TLBuffer() := _ }\n\n  system.chiptopClockGroupsNode := clockDivider.clockNode := clockSelector.clockNode\n\n  // Connect all other requested clocks\n  val slowClockSource = ClockSourceNode(Seq(ClockSourceParameters()))\n  val pllClockSource = ClockSourceNode(Seq(ClockSourceParameters()))\n\n  // The order of the connections to clockSelector.clockNode configures the inputs\n  // of the clockSelector's clockMux. Default to using the slowClockSource,\n  // software should enable the PLL, then switch to the pllClockSource\n  clockSelector.clockNode := slowClockSource\n  clockSelector.clockNode := pllClockSource\n\n  val pllCtrlSink = BundleBridgeSink[FakePLLCtrlBundle]()\n  pllCtrlSink := pllCtrl.ctrlNode\n\n  val debugClockSinkNode = ClockSinkNode(Seq(ClockSinkParameters()))\n  debugClockSinkNode := system.locateTLBusWrapper(p(ExportDebug).slaveWhere).fixedClockNode\n  def debugClockBundle = debugClockSinkNode.in.head._1\n\n  var ports: Seq[Port[_]] = Nil\n\n  override lazy val module = new FlatChipTopImpl\n  class FlatChipTopImpl extends LazyRawModuleImp(this) {\n    //=========================\n    // Clock/reset\n    //=========================\n    val clock_wire = Wire(Input(Clock()))\n    val reset_wire = Wire(Input(AsyncReset()))\n    val (clock_pad, clockIOCell) = IOCell.generateIOFromSignal(clock_wire, \"clock\", p(IOCellKey))\n    val (reset_pad, resetIOCell) = IOCell.generateIOFromSignal(reset_wire, \"reset\", p(IOCellKey))\n\n    slowClockSource.out.unzip._1.map { o =>\n      o.clock := clock_wire\n      o.reset := reset_wire\n    }\n\n    ports = ports :+ ClockPort(() => clock_pad, 100.0)\n    ports = ports :+ ResetPort(() => reset_pad)\n\n    // For a real chip you should replace this ClockSourceAtFreqFromPlusArg\n    // with a blackbox of whatever PLL is being integrated\n    val fake_pll = Module(new ClockSourceAtFreqFromPlusArg(\"pll_freq_mhz\"))\n    fake_pll.io.power := pllCtrlSink.in(0)._1.power\n    fake_pll.io.gate := pllCtrlSink.in(0)._1.gate\n\n    pllClockSource.out.unzip._1.map { o =>\n      o.clock := fake_pll.io.clk\n      o.reset := reset_wire\n    }\n\n    //=========================\n    // Custom Boot\n    //=========================\n    val (custom_boot_pad, customBootIOCell) = IOCell.generateIOFromSignal(system.custom_boot_pin.get.getWrappedValue, \"custom_boot\", p(IOCellKey))\n    ports = ports :+ CustomBootPort(() => custom_boot_pad)\n\n    //=========================\n    // Serialized TileLink\n    //=========================\n    val (serial_tl_pad, serialTLIOCells) = IOCell.generateIOFromSignal(system.serial_tls(0).getWrappedValue, \"serial_tl\", p(IOCellKey))\n    ports = ports :+ SerialTLPort(() => serial_tl_pad, p(SerialTLKey)(0), system.serdessers(0), 0)\n\n    //=========================\n    // JTAG/Debug\n    //=========================\n    val debug = system.debug.get\n    // We never use the PSDIO, so tie it off on-chip\n    system.psd.psd.foreach { _ <> 0.U.asTypeOf(new PSDTestMode) }\n    system.resetctrl.map { rcio => rcio.hartIsInReset.map { _ := false.B } }\n\n    // Tie off extTrigger\n    debug.extTrigger.foreach { t =>\n      t.in.req := false.B\n      t.out.ack := t.out.req\n    }\n    // Tie off disableDebug\n    debug.disableDebug.foreach { d => d := false.B }\n    // Drive JTAG on-chip IOs\n    debug.systemjtag.map { j =>\n      j.reset := ResetCatchAndSync(j.jtag.TCK, debugClockBundle.reset.asBool)\n      j.mfr_id := p(JtagDTMKey).idcodeManufId.U(11.W)\n      j.part_number := p(JtagDTMKey).idcodePartNum.U(16.W)\n      j.version := p(JtagDTMKey).idcodeVersion.U(4.W)\n    }\n\n    Debug.connectDebugClockAndReset(Some(debug), debugClockBundle.clock)\n\n    // Add IOCells for the DMI/JTAG/APB ports\n    require(!debug.clockeddmi.isDefined)\n    require(!debug.apb.isDefined)\n    val (jtag_pad, jtagIOCells) = debug.systemjtag.map { j =>\n      val jtag_wire = Wire(new JTAGChipIO(false))\n      j.jtag.TCK := jtag_wire.TCK\n      j.jtag.TMS := jtag_wire.TMS\n      j.jtag.TDI := jtag_wire.TDI\n      jtag_wire.TDO := j.jtag.TDO.data\n      IOCell.generateIOFromSignal(jtag_wire, \"jtag\", p(IOCellKey), abstractResetAsAsync = true)\n    }.get\n\n    ports = ports :+ JTAGPort(() => jtag_pad)\n\n    //==========================\n    // UART\n    //==========================\n    require(system.uarts.size == 1)\n    val (uart_pad, uartIOCells) = IOCell.generateIOFromSignal(system.uart.head, \"uart_0\", p(IOCellKey))\n    val where = PBUS // TODO fix\n    val bus = system.asInstanceOf[HasTileLinkLocations].locateTLBusWrapper(where)\n    val freqMHz = bus.dtsFrequency.get / 1000000\n    ports = ports :+ UARTPort(() => uart_pad, 0, freqMHz.toInt)\n\n    //==========================\n    // External interrupts (tie off)\n    //==========================\n    system.module.interrupts := DontCare\n  }\n}\n","chipyard:generators/chipyard/src/main/scala/example/FlatTestHarness.scala":"package chipyard.example\n\nimport chisel3._\nimport scala.collection.mutable.{ArrayBuffer, LinkedHashMap}\n\nimport org.chipsalliance.cde.config.{Field, Parameters}\nimport freechips.rocketchip.diplomacy.{LazyModule}\nimport freechips.rocketchip.prci.{ClockSourceAtFreqFromPlusArg, ClockBundle, ClockBundleParameters}\nimport freechips.rocketchip.util.{PlusArg}\nimport freechips.rocketchip.subsystem.{CacheBlockBytes}\nimport freechips.rocketchip.devices.debug.{SimJTAG}\nimport freechips.rocketchip.jtag.{JTAGIO}\nimport testchipip.serdes._\nimport testchipip.uart.{UARTAdapter}\nimport testchipip.dram.{SimDRAM}\nimport testchipip.tsi.{TSIHarness, SimTSI, SerialRAM}\nimport chipyard.harness.{BuildTop}\n\n// A \"flat\" TestHarness that doesn't use IOBinders\n// use with caution.\n// This example is hard-coded to work only for FlatChipTop, and the ChipLikeRocketConfig\nclass FlatTestHarness(implicit val p: Parameters) extends Module {\n  val io = IO(new Bundle {\n    val success = Output(Bool())\n  })\n\n  // This only works with FlatChipTop\n  val lazyDut = LazyModule(new FlatChipTop).suggestName(\"chiptop\")\n  val dut = Module(lazyDut.module)\n\n  // Clock\n  val clock_source = Module(new ClockSourceAtFreqFromPlusArg(\"slow_clk_freq_mhz\"))\n  clock_source.io.power := true.B\n  clock_source.io.gate := false.B\n  dut.clock_pad := clock_source.io.clk\n\n  // Reset\n  dut.reset_pad := reset.asAsyncReset\n\n  // Custom boot\n  dut.custom_boot_pad := PlusArg(\"custom_boot_pin\", width=1)\n\n  // Serialized TL\n  val sVal = p(SerialTLKey)(0)\n  val serialTLManagerParams = sVal.manager.get\n  require(serialTLManagerParams.isMemoryDevice)\n\n  // Figure out which clock drives the harness TLSerdes, based on the port type\n  val serial_ram_clock = dut.serial_tl_pad match {\n    case io: HasClockOut => io.clock_out\n    case io: HasClockIn => clock\n  }\n  dut.serial_tl_pad match {\n    case io: HasClockIn => io.clock_in := clock\n    case io: HasClockOut =>\n  }\n\n  dut.serial_tl_pad match {\n    case pad: DecoupledPhitIO => {\n      withClockAndReset(serial_ram_clock, reset) {\n        // SerialRAM implements the memory regions the chip expects\n        val ram = Module(LazyModule(new SerialRAM(lazyDut.system.serdessers(0), p(SerialTLKey)(0))).module)\n        ram.io.ser.in <> pad.out\n        pad.in <> ram.io.ser.out\n\n        // Allow TSI to master the chip\n        io.success := SimTSI.connect(ram.io.tsi, serial_ram_clock, reset)\n      }\n    }\n  }\n\n  // JTAG\n  val jtag_wire = Wire(new JTAGIO)\n  jtag_wire.TDO.data := dut.jtag_pad.TDO\n  jtag_wire.TDO.driven := true.B\n  dut.jtag_pad.TCK := jtag_wire.TCK\n  dut.jtag_pad.TMS := jtag_wire.TMS\n  dut.jtag_pad.TDI := jtag_wire.TDI\n  val dtm_success = WireInit(false.B)\n  val jtag = Module(new SimJTAG(tickDelay=3)).connect(jtag_wire, clock, reset.asBool, ~(reset.asBool), dtm_success)\n\n  // UART\n  UARTAdapter.connect(Seq(dut.uart_pad))\n}\n","chipyard:generators/chipyard/src/main/scala/example/GCD.scala":"package chipyard.example\n\nimport sys.process._\n\nimport chisel3._\nimport chisel3.util._\nimport chisel3.experimental.{IntParam, BaseModule}\nimport freechips.rocketchip.amba.axi4._\nimport freechips.rocketchip.prci._\nimport freechips.rocketchip.subsystem.{BaseSubsystem, PBUS}\nimport org.chipsalliance.cde.config.{Parameters, Field, Config}\nimport freechips.rocketchip.diplomacy._\nimport freechips.rocketchip.regmapper.{HasRegMap, RegField}\nimport freechips.rocketchip.tilelink._\nimport freechips.rocketchip.util.UIntIsOneOf\n\n// DOC include start: GCD params\ncase class GCDParams(\n  address: BigInt = 0x4000,\n  width: Int = 32,\n  useAXI4: Boolean = false,\n  useBlackBox: Boolean = true,\n  useHLS: Boolean = false)\n// DOC include end: GCD params\n\n// DOC include start: GCD key\ncase object GCDKey extends Field[Option[GCDParams]](None)\n// DOC include end: GCD key\n\nclass GCDIO(val w: Int) extends Bundle {\n  val clock = Input(Clock())\n  val reset = Input(Bool())\n  val input_ready = Output(Bool())\n  val input_valid = Input(Bool())\n  val x = Input(UInt(w.W))\n  val y = Input(UInt(w.W))\n  val output_ready = Input(Bool())\n  val output_valid = Output(Bool())\n  val gcd = Output(UInt(w.W))\n  val busy = Output(Bool())\n}\n\nclass HLSGCDAccelIO(val w: Int) extends Bundle {\n  val ap_clk = Input(Clock())\n  val ap_rst = Input(Reset())\n  val ap_start = Input(Bool())\n  val ap_done = Output(Bool())\n  val ap_idle = Output(Bool())\n  val ap_ready = Output(Bool())\n  val x = Input(UInt(w.W))\n  val y = Input(UInt(w.W))\n  val ap_return = Output(UInt(w.W))\n}\n\nclass GCDTopIO extends Bundle {\n  val gcd_busy = Output(Bool())\n}\n\ntrait HasGCDTopIO {\n  def io: GCDTopIO\n}\n\n// DOC include start: GCD blackbox\nclass GCDMMIOBlackBox(val w: Int) extends BlackBox(Map(\"WIDTH\" -> IntParam(w))) with HasBlackBoxResource {\n  val io = IO(new GCDIO(w))\n  addResource(\"/vsrc/GCDMMIOBlackBox.v\")\n}\n// DOC include end: GCD blackbox\n\n// DOC include start: GCD chisel\nclass GCDMMIOChiselModule(val w: Int) extends Module {\n  val io = IO(new GCDIO(w))\n  val s_idle :: s_run :: s_done :: Nil = Enum(3)\n\n  val state = RegInit(s_idle)\n  val tmp   = Reg(UInt(w.W))\n  val gcd   = Reg(UInt(w.W))\n\n  io.input_ready := state === s_idle\n  io.output_valid := state === s_done\n  io.gcd := gcd\n\n  when (state === s_idle && io.input_valid) {\n    state := s_run\n  } .elsewhen (state === s_run && tmp === 0.U) {\n    state := s_done\n  } .elsewhen (state === s_done && io.output_ready) {\n    state := s_idle\n  }\n\n  when (state === s_idle && io.input_valid) {\n    gcd := io.x\n    tmp := io.y\n  } .elsewhen (state === s_run) {\n    when (gcd > tmp) {\n      gcd := gcd - tmp\n    } .otherwise {\n      tmp := tmp - gcd\n    }\n  }\n\n  io.busy := state =/= s_idle\n}\n// DOC include end: GCD chisel\n\n// DOC include start: HLS blackbox\nclass HLSGCDAccelBlackBox(val w: Int) extends BlackBox with HasBlackBoxPath {\n  val io = IO(new HLSGCDAccelIO(w))\n\n  val chipyardDir = System.getProperty(\"user.dir\")\n  val hlsDir = s\"$chipyardDir/generators/chipyard\"\n  \n  // Run HLS command\n  val make = s\"make -C ${hlsDir}/src/main/resources/hls default\"\n  require (make.! == 0, \"Failed to run HLS\")\n\n  // Add each vlog file\n  addPath(s\"$hlsDir/src/main/resources/vsrc/HLSGCDAccelBlackBox.v\")\n  addPath(s\"$hlsDir/src/main/resources/vsrc/HLSGCDAccelBlackBox_flow_control_loop_pipe.v\")\n}\n// DOC include end: HLS blackbox\n\n// DOC include start: GCD router\nclass GCDTL(params: GCDParams, beatBytes: Int)(implicit p: Parameters) extends ClockSinkDomain(ClockSinkParameters())(p) {\n  val device = new SimpleDevice(\"gcd\", Seq(\"ucbbar,gcd\")) \n  val node = TLRegisterNode(Seq(AddressSet(params.address, 4096-1)), device, \"reg/control\", beatBytes=beatBytes)\n\n  override lazy val module = new GCDImpl\n  class GCDImpl extends Impl with HasGCDTopIO {\n    val io = IO(new GCDTopIO)\n    withClockAndReset(clock, reset) {\n      // How many clock cycles in a PWM cycle?\n      val x = Reg(UInt(params.width.W))\n      val y = Wire(new DecoupledIO(UInt(params.width.W)))\n      val gcd = Wire(new DecoupledIO(UInt(params.width.W)))\n      val status = Wire(UInt(2.W))\n\n      val impl_io = if (params.useBlackBox) {\n        val impl = Module(new GCDMMIOBlackBox(params.width))\n        impl.io\n      } else {\n        val impl = Module(new GCDMMIOChiselModule(params.width))\n        impl.io\n      }\n\n      impl_io.clock := clock\n      impl_io.reset := reset.asBool\n\n      impl_io.x := x\n      impl_io.y := y.bits\n      impl_io.input_valid := y.valid\n      y.ready := impl_io.input_ready\n\n      gcd.bits := impl_io.gcd\n      gcd.valid := impl_io.output_valid\n      impl_io.output_ready := gcd.ready\n\n      status := Cat(impl_io.input_ready, impl_io.output_valid)\n      io.gcd_busy := impl_io.busy\n\n// DOC include start: GCD instance regmap\n      node.regmap(\n        0x00 -> Seq(\n          RegField.r(2, status)), // a read-only register capturing current status\n        0x04 -> Seq(\n          RegField.w(params.width, x)), // a plain, write-only register\n        0x08 -> Seq(\n          RegField.w(params.width, y)), // write-only, y.valid is set on write\n        0x0C -> Seq(\n          RegField.r(params.width, gcd))) // read-only, gcd.ready is set on read\n// DOC include end: GCD instance regmap\n    }\n  }\n}\n\nclass GCDAXI4(params: GCDParams, beatBytes: Int)(implicit p: Parameters) extends ClockSinkDomain(ClockSinkParameters())(p) {\n  val node = AXI4RegisterNode(AddressSet(params.address, 4096-1), beatBytes=beatBytes)\n  override lazy val module = new GCDImpl\n  class GCDImpl extends Impl with HasGCDTopIO {\n    val io = IO(new GCDTopIO)\n    withClockAndReset(clock, reset) {\n      // How many clock cycles in a PWM cycle?\n      val x = Reg(UInt(params.width.W))\n      val y = Wire(new DecoupledIO(UInt(params.width.W)))\n      val gcd = Wire(new DecoupledIO(UInt(params.width.W)))\n      val status = Wire(UInt(2.W))\n\n      val impl_io = if (params.useBlackBox) {\n        val impl = Module(new GCDMMIOBlackBox(params.width))\n        impl.io\n      } else {\n        val impl = Module(new GCDMMIOChiselModule(params.width))\n        impl.io\n      }\n\n      impl_io.clock := clock\n      impl_io.reset := reset.asBool\n\n      impl_io.x := x\n      impl_io.y := y.bits\n      impl_io.input_valid := y.valid\n      y.ready := impl_io.input_ready\n\n      gcd.bits := impl_io.gcd\n      gcd.valid := impl_io.output_valid\n      impl_io.output_ready := gcd.ready\n\n      status := Cat(impl_io.input_ready, impl_io.output_valid)\n      io.gcd_busy := impl_io.busy\n\n      node.regmap(\n        0x00 -> Seq(\n          RegField.r(2, status)), // a read-only register capturing current status\n        0x04 -> Seq(\n          RegField.w(params.width, x)), // a plain, write-only register\n        0x08 -> Seq(\n          RegField.w(params.width, y)), // write-only, y.valid is set on write\n        0x0C -> Seq(\n          RegField.r(params.width, gcd))) // read-only, gcd.ready is set on read\n    }\n  }\n}\n// DOC include end: GCD router\n\nclass HLSGCDAccel(params: GCDParams, beatBytes: Int)(implicit p: Parameters) extends ClockSinkDomain(ClockSinkParameters())(p) {\n  val device = new SimpleDevice(\"hlsgcdaccel\", Seq(\"ucbbar,hlsgcdaccel\")) \n  val node = TLRegisterNode(Seq(AddressSet(params.address, 4096-1)), device, \"reg/control\", beatBytes=beatBytes)\n\n  override lazy val module = new HLSGCDAccelImpl\n  class HLSGCDAccelImpl extends Impl with HasGCDTopIO {\n    val io = IO(new GCDTopIO)\n    withClockAndReset(clock, reset) {\n      val x = Reg(UInt(params.width.W))\n      val y = Wire(new DecoupledIO(UInt(params.width.W)))\n      val y_reg = Reg(UInt(params.width.W))\n      val gcd = Wire(new DecoupledIO(UInt(params.width.W)))\n      val gcd_reg = Reg(UInt(params.width.W))\n      val status = Wire(UInt(2.W))\n\n      val impl = Module(new HLSGCDAccelBlackBox(params.width))\n\n      impl.io.ap_clk := clock\n      impl.io.ap_rst := reset\n\n      val s_idle :: s_busy :: Nil = Enum(2)\n      val state = RegInit(s_idle)\n      val result_valid = RegInit(false.B)\n      when (state === s_idle && y.valid) { \n        state := s_busy\n        result_valid := false.B\n        y_reg := y.bits \n      } .elsewhen (state === s_busy && impl.io.ap_done) {\n        state := s_idle\n        result_valid := true.B\n        gcd_reg := impl.io.ap_return\n      }\n\n      impl.io.ap_start := state === s_busy\n\n      gcd.valid := result_valid\n      status := Cat(impl.io.ap_idle, result_valid)\n      \n      impl.io.x := x\n      impl.io.y := y_reg\n      y.ready := impl.io.ap_idle\n      gcd.bits := gcd_reg\n\n      io.gcd_busy := !impl.io.ap_idle\n\n      node.regmap(\n        0x00 -> Seq(\n          RegField.r(2, status)), // a read-only register capturing current status\n        0x04 -> Seq(\n          RegField.w(params.width, x)), // a plain, write-only register\n        0x08 -> Seq(\n          RegField.w(params.width, y)), // write-only, y.valid is set on write\n        0x0C -> Seq(\n          RegField.r(params.width, gcd))) // read-only, gcd.ready is set on read\n    }\n  }\n}\n\n// DOC include start: GCD lazy trait\ntrait CanHavePeripheryGCD { this: BaseSubsystem =>\n  private val portName = \"gcd\"\n\n  private val pbus = locateTLBusWrapper(PBUS)\n\n  // Only build if we are using the TL (nonAXI4) version\n  val gcd_busy = p(GCDKey) match {\n    case Some(params) => {\n      val gcd = if (params.useAXI4) {\n        val gcd = LazyModule(new GCDAXI4(params, pbus.beatBytes)(p))\n        gcd.clockNode := pbus.fixedClockNode\n        pbus.coupleTo(portName) {\n          gcd.node :=\n          AXI4Buffer () :=\n          TLToAXI4 () :=\n          // toVariableWidthSlave doesn't use holdFirstDeny, which TLToAXI4() needsx\n          TLFragmenter(pbus.beatBytes, pbus.blockBytes, holdFirstDeny = true) := _\n        }\n        gcd\n      } else if (params.useHLS) {\n        val gcd = LazyModule(new HLSGCDAccel(params, pbus.beatBytes)(p))\n        gcd.clockNode := pbus.fixedClockNode\n        pbus.coupleTo(portName) { gcd.node := TLFragmenter(pbus.beatBytes, pbus.blockBytes) := _ }\n        gcd\n      } else {\n        val gcd = LazyModule(new GCDTL(params, pbus.beatBytes)(p))\n        gcd.clockNode := pbus.fixedClockNode\n        pbus.coupleTo(portName) { gcd.node := TLFragmenter(pbus.beatBytes, pbus.blockBytes) := _ }\n        gcd\n      }\n      val gcd_busy = InModuleBody {\n        val busy = IO(Output(Bool())).suggestName(\"gcd_busy\")\n        busy := gcd.module.io.gcd_busy\n        busy\n      }\n      Some(gcd_busy)\n    }\n    case None => None\n  }\n}\n// DOC include end: GCD lazy trait\n\n// DOC include start: GCD config fragment\nclass WithGCD(useAXI4: Boolean = false, useBlackBox: Boolean = false, useHLS: Boolean = false) extends Config((site, here, up) => {\n  case GCDKey => {\n    // useHLS cannot be used with useAXI4 and useBlackBox\n    assert(!useHLS || (useHLS && !useAXI4 && !useBlackBox)) \n    Some(GCDParams(useAXI4 = useAXI4, useBlackBox = useBlackBox, useHLS = useHLS))\n  }\n})\n// DOC include end: GCD config fragment\n","chipyard:generators/chipyard/src/main/scala/example/InitZero.scala":"package chipyard.example\n\nimport chisel3._\nimport chisel3.util._\nimport freechips.rocketchip.subsystem.{BaseSubsystem, CacheBlockBytes, FBUS}\nimport org.chipsalliance.cde.config.{Parameters, Field, Config}\nimport freechips.rocketchip.diplomacy.{LazyModule, LazyModuleImp, IdRange}\nimport freechips.rocketchip.tilelink._\n\ncase class InitZeroConfig(base: BigInt, size: BigInt)\ncase object InitZeroKey extends Field[Option[InitZeroConfig]](None)\n\nclass InitZero(implicit p: Parameters) extends LazyModule {\n  val node = TLClientNode(Seq(TLMasterPortParameters.v1(Seq(TLClientParameters(\n    name = \"init-zero\", sourceId = IdRange(0, 1))))))\n\n  lazy val module = new InitZeroModuleImp(this)\n}\n\nclass InitZeroModuleImp(outer: InitZero) extends LazyModuleImp(outer) {\n  val config = p(InitZeroKey).get\n\n  val (mem, edge) = outer.node.out(0)\n  val addrBits = edge.bundle.addressBits\n  val blockBytes = p(CacheBlockBytes)\n\n  require(config.size % blockBytes == 0)\n\n  val s_init :: s_write :: s_resp :: s_done :: Nil = Enum(4)\n  val state = RegInit(s_init)\n\n  val addr = Reg(UInt(addrBits.W))\n  val bytesLeft = Reg(UInt(log2Ceil(config.size+1).W))\n\n  mem.a.valid := state === s_write\n  mem.a.bits := edge.Put(\n    fromSource = 0.U,\n    toAddress = addr,\n    lgSize = log2Ceil(blockBytes).U,\n    data = 0.U)._2\n  mem.d.ready := state === s_resp\n\n  when (state === s_init) {\n    addr := config.base.U\n    bytesLeft := config.size.U\n    state := s_write\n  }\n\n  when (edge.done(mem.a)) {\n    addr := addr + blockBytes.U\n    bytesLeft := bytesLeft - blockBytes.U\n    state := s_resp\n  }\n\n  when (mem.d.fire) {\n    state := Mux(bytesLeft === 0.U, s_done, s_write)\n  }\n}\n\ntrait CanHavePeripheryInitZero { this: BaseSubsystem =>\n  implicit val p: Parameters\n\n  p(InitZeroKey) .map { k =>\n    val fbus = locateTLBusWrapper(FBUS)\n    val initZero = fbus { LazyModule(new InitZero()(p)) }\n    fbus.coupleFrom(\"init-zero\") { _ := initZero.node }\n  }\n}\n\n\n// DOC include start: WithInitZero\nclass WithInitZero(base: BigInt, size: BigInt) extends Config((site, here, up) => {\n  case InitZeroKey => Some(InitZeroConfig(base, size))\n})\n// DOC include end: WithInitZero\n","chipyard:generators/chipyard/src/main/scala/example/NodeTypes.scala":"package chipyard.example\n\nimport org.chipsalliance.cde.config.Parameters\nimport freechips.rocketchip.diplomacy._\nimport freechips.rocketchip.tilelink._\n\n// These modules are not meant to be synthesized.\n// They are used as examples in the documentation and are only here\n// to check that they compile.\n\n// DOC include start: MyClient\nclass MyClient(implicit p: Parameters) extends LazyModule {\n  val node = TLClientNode(Seq(TLMasterPortParameters.v1(Seq(TLClientParameters(\n    name = \"my-client\",\n    sourceId = IdRange(0, 4),\n    requestFifo = true,\n    visibility = Seq(AddressSet(0x10000, 0xffff)))))))\n\n  lazy val module = new LazyModuleImp(this) {\n    val (tl, edge) = node.out(0)\n\n    // Rest of code here\n  }\n}\n// DOC include end: MyClient\n\n// DOC include start: MyManager\nclass MyManager(implicit p: Parameters) extends LazyModule {\n  val device = new SimpleDevice(\"my-device\", Seq(\"tutorial,my-device0\"))\n  val beatBytes = 8\n  val node = TLManagerNode(Seq(TLSlavePortParameters.v1(Seq(TLManagerParameters(\n    address = Seq(AddressSet(0x20000, 0xfff)),\n    resources = device.reg,\n    regionType = RegionType.UNCACHED,\n    executable = true,\n    supportsArithmetic = TransferSizes(1, beatBytes),\n    supportsLogical = TransferSizes(1, beatBytes),\n    supportsGet = TransferSizes(1, beatBytes),\n    supportsPutFull = TransferSizes(1, beatBytes),\n    supportsPutPartial = TransferSizes(1, beatBytes),\n    supportsHint = TransferSizes(1, beatBytes),\n    fifoId = Some(0))), beatBytes)))\n\n  lazy val module = new LazyModuleImp(this) {\n    val (tl, edge) = node.in(0)\n  }\n}\n// DOC include end: MyManager\n\n// DOC include start: MyClient1+MyClient2\nclass MyClient1(implicit p: Parameters) extends LazyModule {\n  val node = TLClientNode(Seq(TLMasterPortParameters.v1(Seq(TLClientParameters(\n    \"my-client1\", IdRange(0, 1))))))\n\n  lazy val module = new LazyModuleImp(this) {\n    // ...\n  }\n}\n\nclass MyClient2(implicit p: Parameters) extends LazyModule {\n  val node = TLClientNode(Seq(TLMasterPortParameters.v1(Seq(TLClientParameters(\n    \"my-client2\", IdRange(0, 1))))))\n\n  lazy val module = new LazyModuleImp(this) {\n    // ...\n  }\n}\n// DOC include end: MyClient1+MyClient2\n\n// DOC include start: MyClientGroup\nclass MyClientGroup(implicit p: Parameters) extends LazyModule {\n  val client1 = LazyModule(new MyClient1)\n  val client2 = LazyModule(new MyClient2)\n  val node = TLIdentityNode()\n\n  node := client1.node\n  node := client2.node\n\n  lazy val module = new LazyModuleImp(this) {\n    // Nothing to do here\n  }\n}\n// DOC include end: MyClientGroup\n\n// DOC include start: MyManagerGroup\nclass MyManager1(beatBytes: Int)(implicit p: Parameters) extends LazyModule {\n  val node = TLManagerNode(Seq(TLSlavePortParameters.v1(Seq(TLManagerParameters(\n    address = Seq(AddressSet(0x0, 0xfff)))), beatBytes)))\n\n  lazy val module = new LazyModuleImp(this) {\n    // ...\n  }\n}\n\nclass MyManager2(beatBytes: Int)(implicit p: Parameters) extends LazyModule {\n  val node = TLManagerNode(Seq(TLSlavePortParameters.v1(Seq(TLManagerParameters(\n    address = Seq(AddressSet(0x1000, 0xfff)))), beatBytes)))\n\n  lazy val module = new LazyModuleImp(this) {\n    // ...\n  }\n}\n\nclass MyManagerGroup(beatBytes: Int)(implicit p: Parameters) extends LazyModule {\n  val man1 = LazyModule(new MyManager1(beatBytes))\n  val man2 = LazyModule(new MyManager2(beatBytes))\n  val node = TLIdentityNode()\n\n  man1.node := node\n  man2.node := node\n\n  lazy val module = new LazyModuleImp(this) {\n    // Nothing to do here\n  }\n}\n// DOC include end: MyManagerGroup\n\n// DOC include start: MyClientManagerComplex\nclass MyClientManagerComplex(implicit p: Parameters) extends LazyModule {\n  val client = LazyModule(new MyClientGroup)\n  val manager = LazyModule(new MyManagerGroup(8))\n\n  manager.node :=* client.node\n\n  lazy val module = new LazyModuleImp(this) {\n    // Nothing to do here\n  }\n}\n// DOC include end: MyClientManagerComplex\n","chipyard:generators/chipyard/src/main/scala/example/RegisterNodeExample.scala":"// DOC include start: MyDeviceController\n\nimport chisel3._\nimport chisel3.util._\nimport org.chipsalliance.cde.config.Parameters\nimport freechips.rocketchip.diplomacy._\nimport freechips.rocketchip.regmapper._\nimport freechips.rocketchip.tilelink.TLRegisterNode\n\nclass MyDeviceController(implicit p: Parameters) extends LazyModule {\n  val device = new SimpleDevice(\"my-device\", Seq(\"tutorial,my-device0\"))\n  val node = TLRegisterNode(\n    address = Seq(AddressSet(0x10028000, 0xfff)),\n    device = device,\n    beatBytes = 8,\n    concurrency = 1)\n\n  lazy val module = new LazyModuleImp(this) {\n    val bigReg = RegInit(0.U(64.W))\n    val mediumReg = RegInit(0.U(32.W))\n    val smallReg = RegInit(0.U(16.W))\n\n    val tinyReg0 = RegInit(0.U(4.W))\n    val tinyReg1 = RegInit(0.U(4.W))\n\n    node.regmap(\n      0x00 -> Seq(RegField(64, bigReg)),\n      0x08 -> Seq(RegField(32, mediumReg)),\n      0x0C -> Seq(RegField(16, smallReg)),\n      0x0E -> Seq(\n        RegField(4, tinyReg0),\n        RegField(4, tinyReg1)))\n  }\n}\n\n// DOC include end: MyDeviceController\n\n// DOC include start: MyAXI4DeviceController\nimport freechips.rocketchip.amba.axi4.AXI4RegisterNode\n\nclass MyAXI4DeviceController(implicit p: Parameters) extends LazyModule {\n  val node = AXI4RegisterNode(\n    address = AddressSet(0x10029000, 0xfff),\n    beatBytes = 8,\n    concurrency = 1)\n\n  lazy val module = new LazyModuleImp(this) {\n    val bigReg = RegInit(0.U(64.W))\n    val mediumReg = RegInit(0.U(32.W))\n    val smallReg = RegInit(0.U(16.W))\n\n    val tinyReg0 = RegInit(0.U(4.W))\n    val tinyReg1 = RegInit(0.U(4.W))\n\n    node.regmap(\n      0x00 -> Seq(RegField(64, bigReg)),\n      0x08 -> Seq(RegField(32, mediumReg)),\n      0x0C -> Seq(RegField(16, smallReg)),\n      0x0E -> Seq(\n        RegField(4, tinyReg0),\n        RegField(4, tinyReg1)))\n  }\n}\n// DOC include end: MyAXI4DeviceController\n\nclass MyQueueRegisters(implicit p: Parameters) extends LazyModule {\n  val device = new SimpleDevice(\"my-queue\", Seq(\"tutorial,my-queue0\"))\n  val node = TLRegisterNode(\n    address = Seq(AddressSet(0x1002A000, 0xfff)),\n    device = device,\n    beatBytes = 8,\n    concurrency = 1)\n\n  lazy val module = new LazyModuleImp(this) {\n// DOC include start: MyQueueRegisters\n    // 4-entry 64-bit queue\n    val queue = Module(new Queue(UInt(64.W), 4))\n\n    node.regmap(\n      0x00 -> Seq(RegField(64, queue.io.deq, queue.io.enq)))\n// DOC include end: MyQueueRegisters\n  }\n}\n\nclass MySeparateQueueRegisters(implicit p: Parameters) extends LazyModule {\n  val device = new SimpleDevice(\"my-queue\", Seq(\"tutorial,my-queue1\"))\n  val node = TLRegisterNode(\n    address = Seq(AddressSet(0x1002B000, 0xfff)),\n    device = device,\n    beatBytes = 8,\n    concurrency = 1)\n\n  lazy val module = new LazyModuleImp(this) {\n    val queue = Module(new Queue(UInt(64.W), 4))\n\n// DOC include start: MySeparateQueueRegisters\n    node.regmap(\n      0x00 -> Seq(RegField.r(64, queue.io.deq)),\n      0x08 -> Seq(RegField.w(64, queue.io.enq)))\n// DOC include end: MySeparateQueueRegisters\n  }\n}\n\nclass MyCounterRegisters(implicit p: Parameters) extends LazyModule {\n  val device = new SimpleDevice(\"my-counters\", Seq(\"tutorial,my-counters0\"))\n  val node = TLRegisterNode(\n    address = Seq(AddressSet(0x1002C000, 0xfff)),\n    device = device,\n    beatBytes = 8,\n    concurrency = 1)\n\n  lazy val module = new LazyModuleImp(this) {\n// DOC include start: MyCounterRegisters\n    val counter = RegInit(0.U(64.W))\n\n    def readCounter(ready: Bool): (Bool, UInt) = {\n      when (ready) { counter := counter - 1.U }\n      // (ready, bits)\n      (true.B, counter)\n    }\n\n    def writeCounter(valid: Bool, bits: UInt): Bool = {\n      when (valid) { counter := counter + 1.U }\n      // Ignore bits\n      // Return ready\n      true.B\n    }\n\n    node.regmap(\n      0x00 -> Seq(RegField.r(64, readCounter(_))),\n      0x08 -> Seq(RegField.w(64, writeCounter(_, _))))\n// DOC include end: MyCounterRegisters\n  }\n}\n\nclass MyCounterReqRespRegisters(implicit p: Parameters) extends LazyModule {\n  val device = new SimpleDevice(\"my-counters\", Seq(\"tutorial,my-counters1\"))\n  val node = TLRegisterNode(\n    address = Seq(AddressSet(0x1002D000, 0xfff)),\n    device = device,\n    beatBytes = 8,\n    concurrency = 1)\n\n  lazy val module = new LazyModuleImp(this) {\n// DOC include start: MyCounterReqRespRegisters\n    val counter = RegInit(0.U(64.W))\n\n    def readCounter(ivalid: Bool, oready: Bool): (Bool, Bool, UInt) = {\n      val responding = RegInit(false.B)\n\n      when (ivalid && !responding) { responding := true.B }\n\n      when (responding && oready) {\n        counter := counter - 1.U\n        responding := false.B\n      }\n\n      // (iready, ovalid, obits)\n      (!responding, responding, counter)\n    }\n\n    def writeCounter(ivalid: Bool, oready: Bool, ibits: UInt): (Bool, Bool) = {\n      val responding = RegInit(false.B)\n\n      when (ivalid && !responding) { responding := true.B }\n\n      when (responding && oready) {\n        counter := counter + 1.U\n        responding := false.B\n      }\n\n      // (iready, ovalid)\n      (!responding, responding)\n    }\n\n    node.regmap(\n      0x00 -> Seq(RegField.r(64, readCounter(_, _))),\n      0x08 -> Seq(RegField.w(64, writeCounter(_, _, _))))\n// DOC include end: MyCounterReqRespRegisters\n  }\n}\n","chipyard:generators/chipyard/src/main/scala/example/TutorialTile.scala":"package chipyard.example\n\nimport chisel3._\nimport chisel3.util._\n\nimport org.chipsalliance.cde.config._\nimport freechips.rocketchip.subsystem._\nimport freechips.rocketchip.devices.tilelink._\nimport freechips.rocketchip.diplomacy._\nimport freechips.rocketchip.rocket._\nimport freechips.rocketchip.subsystem.{RocketCrossingParams}\nimport freechips.rocketchip.tilelink._\nimport freechips.rocketchip.interrupts._\nimport freechips.rocketchip.util._\nimport freechips.rocketchip.tile._\nimport freechips.rocketchip.amba.axi4._\nimport freechips.rocketchip.prci._\n\n// Example parameter class copied from CVA6, not included in documentation but for compile check only\n// If you are here for documentation, DO NOT copy MyCoreParams and MyTileParams directly - always figure\n// out what parameters you need before you write the parameter class\ncase class MyCoreParams(\n  bootFreqHz: BigInt = BigInt(1700000000),\n  rasEntries: Int = 4,\n  btbEntries: Int = 16,\n  bhtEntries: Int = 16,\n  enableToFromHostCaching: Boolean = false,\n) extends CoreParams {\n  val xLen: Int = 32\n  val pgLevels: Int = 2\n  val useVM: Boolean = true\n  val useHypervisor: Boolean = false\n  val useUser: Boolean = true\n  val useSupervisor: Boolean = false\n  val useDebug: Boolean = true\n  val useAtomics: Boolean = true\n  val useAtomicsOnlyForIO: Boolean = false // copied from Rocket\n  val useCompressed: Boolean = true\n  override val useVector: Boolean = false\n  val useSCIE: Boolean = false\n  val useRVE: Boolean = false\n  val mulDiv: Option[MulDivParams] = Some(MulDivParams()) // copied from Rocket\n  val fpu: Option[FPUParams] = Some(FPUParams()) // copied fma latencies from Rocket\n  val nLocalInterrupts: Int = 0\n  val useNMI: Boolean = false\n  val nPTECacheEntries: Int = 0 // TODO: Check\n  val nPMPs: Int = 0 // TODO: Check\n  val pmpGranularity: Int = 4 // copied from Rocket\n  val nBreakpoints: Int = 0 // TODO: Check\n  val useBPWatch: Boolean = false\n  val mcontextWidth: Int = 0\n  val scontextWidth: Int = 0\n  val nPerfCounters: Int = 29\n  val haveBasicCounters: Boolean = true\n  val haveFSDirty: Boolean = false\n  val misaWritable: Boolean = false\n  val haveCFlush: Boolean = false\n  val nL2TLBEntries: Int = 512 // copied from Rocket\n  val nL2TLBWays: Int = 1\n  val mtvecInit: Option[BigInt] = Some(BigInt(0)) // copied from Rocket\n  val mtvecWritable: Boolean = true // copied from Rocket\n  val instBits: Int = if (useCompressed) 16 else 32\n  val lrscCycles: Int = 80 // copied from Rocket\n  val decodeWidth: Int = 1 // TODO: Check\n  val fetchWidth: Int = 1 // TODO: Check\n  val retireWidth: Int = 2\n  val traceHasWdata: Boolean = false\n  val useConditionalZero = false\n  val useZba: Boolean = false\n  val useZbb: Boolean = false\n  val useZbs: Boolean = false\n}\n\n// DOC include start: CanAttachTile\ncase class MyTileAttachParams(\n  tileParams: MyTileParams,\n  crossingParams: RocketCrossingParams\n) extends CanAttachTile {\n  type TileType = MyTile\n  val lookup = PriorityMuxHartIdFromSeq(Seq(tileParams))\n}\n// DOC include end: CanAttachTile\n\ncase class MyTileParams(\n  name: Option[String] = Some(\"my_tile\"),\n  tileId: Int = 0,\n  trace: Boolean = false,\n  val core: MyCoreParams = MyCoreParams()\n) extends InstantiableTileParams[MyTile]\n{\n  val beuAddr: Option[BigInt] = None\n  val blockerCtrlAddr: Option[BigInt] = None\n  val btb: Option[BTBParams] = Some(BTBParams())\n  val boundaryBuffers: Boolean = false\n  val dcache: Option[DCacheParams] = Some(DCacheParams())\n  val icache: Option[ICacheParams] = Some(ICacheParams())\n  val clockSinkParams: ClockSinkParameters = ClockSinkParameters()\n  def instantiate(crossing: HierarchicalElementCrossingParamsLike, lookup: LookupByHartIdImpl)(implicit p: Parameters): MyTile = {\n    new MyTile(this, crossing, lookup)\n  }\n  val baseName = name.getOrElse(\"my_tile\")\n  val uniqueName = s\"${baseName}_$tileId\"\n}\n\n// DOC include start: Tile class\nclass MyTile(\n  val myParams: MyTileParams,\n  crossing: ClockCrossingType,\n  lookup: LookupByHartIdImpl,\n  q: Parameters)\n  extends BaseTile(myParams, crossing, lookup, q)\n  with SinksExternalInterrupts\n  with SourcesExternalNotifications\n{\n\n  // Private constructor ensures altered LazyModule.p is used implicitly\n  def this(params: MyTileParams, crossing: HierarchicalElementCrossingParamsLike, lookup: LookupByHartIdImpl)(implicit p: Parameters) =\n    this(params, crossing.crossingType, lookup, p)\n\n  // Require TileLink nodes\n  val intOutwardNode = None\n  val masterNode = visibilityNode\n  val slaveNode = TLIdentityNode()\n\n  // Implementation class (See below)\n  override lazy val module = new MyTileModuleImp(this)\n\n  // Required entry of CPU device in the device tree for interrupt purpose\n  val cpuDevice: SimpleDevice = new SimpleDevice(\"cpu\", Seq(\"my-organization,my-cpu\", \"riscv\")) {\n    override def parent = Some(ResourceAnchors.cpus)\n    override def describe(resources: ResourceBindings): Description = {\n      val Description(name, mapping) = super.describe(resources)\n      Description(name, mapping ++\n                        cpuProperties ++\n                        nextLevelCacheProperty ++\n                        tileProperties)\n    }\n  }\n\n  ResourceBinding {\n    Resource(cpuDevice, \"reg\").bind(ResourceAddress(tileId))\n  }\n\n  // TODO: Create TileLink nodes and connections here.\n  // DOC include end: Tile class\n\n  // DOC include start: AXI4 node\n  // # of bits used in TileLink ID for master node. 4 bits can support 16 master nodes, but you can have a longer ID if you need more.\n  val idBits = 4\n  val memAXI4Node = AXI4MasterNode(\n    Seq(AXI4MasterPortParameters(\n      masters = Seq(AXI4MasterParameters(\n        name = \"myPortName\",\n        id = IdRange(0, 1 << idBits))))))\n  val memoryTap = TLIdentityNode() // Every bus connection should have their own tap node\n  // DOC include end: AXI4 node\n\n  // DOC include start: AXI4 convert\n  (tlMasterXbar.node  // tlMasterXbar is the bus crossbar to be used when this core / tile is acting as a master; otherwise, use tlSlaveXBar\n    := memoryTap\n    := TLBuffer()\n    := TLFIFOFixer(TLFIFOFixer.all) // fix FIFO ordering\n    := TLWidthWidget(masterPortBeatBytes) // reduce size of TL\n    := AXI4ToTL() // convert to TL\n    := AXI4UserYanker(Some(2)) // remove user field on AXI interface. need but in reality user intf. not needed\n    := AXI4Fragmenter() // deal with multi-beat xacts\n    := memAXI4Node) // The custom node, see below\n  // DOC include end: AXI4 convert\n\n}\n\n// DOC include start: Implementation class\nclass MyTileModuleImp(outer: MyTile) extends BaseTileModuleImp(outer){\n  // annotate the parameters\n  Annotated.params(this, outer.myParams)\n\n  // TODO: Create the top module of the core and connect it with the ports in \"outer\"\n\n  // If your core is in Verilog (assume your blackbox is called \"MyCoreBlackbox\"), instantiate it here like\n  //   val core = Module(new MyCoreBlackbox(params...))\n  // (as described in the blackbox tutorial) and connect appropriate signals. See the blackbox tutorial\n  // (link on the top of the page) for more info.\n  // You can look at https://github.com/ucb-bar/cva6-wrapper/blob/master/src/main/scala/CVA6Tile.scala\n  // for a Verilog example.\n\n  // If your core is in Chisel, you can simply instantiate the top module here like other Chisel module\n  // and connect appropriate signal. You can even implement this class as your top module.\n  // See https://github.com/riscv-boom/riscv-boom/blob/master/src/main/scala/common/tile.scala and\n  // https://github.com/chipsalliance/rocket-chip/blob/master/src/main/scala/tile/RocketTile.scala for\n  // Chisel example.\n\n  // DOC include end: Implementation class\n\n  // DOC include start: connect interrupt\n  // For example, our core support debug interrupt and machine-level interrupt, and suppose the following two signals\n  // are the interrupt inputs to the core. (DO NOT COPY this code - if your core treat each type of interrupt differently,\n  // you need to connect them to different interrupt ports of your core)\n  val debug_i = Wire(Bool())\n  val mtip_i = Wire(Bool())\n  // We create a bundle here and decode the interrupt.\n  val int_bundle = new TileInterrupts()\n  outer.decodeCoreInterrupts(int_bundle)\n  debug_i := int_bundle.debug\n  mtip_i := int_bundle.meip & int_bundle.msip & int_bundle.mtip\n  // DOC include end: connect interrupt\n\n  // DOC include start: raise interrupt\n  // This is a demo. You should call these function according to your core\n  // Suppose that the following signal is from the decoder indicating a WFI instruction is received.\n  val wfi_o = Wire(Bool())\n  outer.reportWFI(Some(wfi_o))\n  // Suppose that the following signal indicate an unreconverable hardware error.\n  val halt_o = Wire(Bool())\n  outer.reportHalt(Some(halt_o))\n  // Suppose that our core never stall for a long time / stop retiring. Use None to indicate that this interrupt never fires.\n  outer.reportCease(None)\n  // DOC include end: raise interrupt\n\n  // DOC include start: AXI4 connect\n  outer.memAXI4Node.out foreach { case (out, edgeOut) =>\n    // Connect your module IO port to \"out\"\n    // The type of \"out\" here is AXI4Bundle, which is defined in generators/rocket-chip/src/main/scala/amba/axi4/Bundles.scala\n    // Please refer to this file for the definition of the ports.\n    // If you are using APB, check APBBundle in generators/rocket-chip/src/main/scala/amba/apb/Bundles.scala\n    // If you are using AHB, check AHBSlaveBundle or AHBMasterBundle in generators/rocket-chip/src/main/scala/amba/ahb/Bundles.scala\n    // (choose one depends on the type of AHB node you create)\n    // If you are using AXIS, check AXISBundle and AXISBundleBits in generators/rocket-chip/src/main/scala/amba/axis/Bundles.scala\n  }\n  // DOC include end: AXI4 connect\n\n}\n\n// DOC include start: Config fragment\nclass WithNMyCores(n: Int = 1) extends Config((site, here, up) => {\n  case TilesLocated(InSubsystem) => {\n    // Calculate the next available hart ID (since hart ID cannot be duplicated)\n    val prev = up(TilesLocated(InSubsystem), site)\n    val idOffset = up(NumTiles)\n    // Create TileAttachParams for every core to be instantiated\n    (0 until n).map { i =>\n      MyTileAttachParams(\n        tileParams = MyTileParams(tileId = i + idOffset),\n        crossingParams = RocketCrossingParams()\n      )\n    } ++ prev\n  }\n  // Configurate # of bytes in one memory / IO transaction. For RV64, one load/store instruction can transfer 8 bytes at most.\n  case SystemBusKey => up(SystemBusKey, site).copy(beatBytes = 8)\n  case NumTiles => up(NumTiles) + n\n})\n// DOC include end: Config fragment\n","chipyard:generators/chipyard/src/main/scala/example/dsptools/DspBlocks.scala":"package chipyard.example\n\nimport chisel3._\nimport chisel3.util._\nimport dspblocks._\nimport dsptools.numbers._\nimport freechips.rocketchip.amba.axi4stream._\nimport org.chipsalliance.cde.config.Parameters\nimport freechips.rocketchip.diplomacy._\nimport freechips.rocketchip.regmapper._\nimport freechips.rocketchip.tilelink._\nimport freechips.rocketchip.subsystem._\n\n/**\n  * The memory interface writes entries into the queue.\n  * They stream out the streaming interface\n  * @param depth number of entries in the queue\n  * @param streamParameters parameters for the stream node\n  * @param p\n  */\nabstract class WriteQueue[D, U, E, O, B <: Data]\n(\n  val depth: Int,\n  val streamParameters: AXI4StreamMasterParameters = AXI4StreamMasterParameters()\n)(implicit p: Parameters) extends DspBlock[D, U, E, O, B] with HasCSR {\n  // stream node, output only\n  val streamNode = AXI4StreamMasterNode(streamParameters)\n\n  lazy val module = new LazyModuleImp(this) {\n    require(streamNode.out.length == 1)\n\n    // get the output bundle associated with the AXI4Stream node\n    val out = streamNode.out.head._1\n    // width (in bits) of the output interface\n    val width = out.params.n * 8\n    // instantiate a queue\n    val queue = Module(new Queue(UInt(out.params.dataBits.W), depth))\n    // connect queue output to streaming output\n    out.valid := queue.io.deq.valid\n    out.bits.data := queue.io.deq.bits\n    // don't use last\n    out.bits.last := false.B\n    queue.io.deq.ready := out.ready\n\n    regmap(\n      // each write adds an entry to the queue\n      0x0 -> Seq(RegField.w(width, queue.io.enq)),\n      // read the number of entries in the queue\n      (width+7)/8 -> Seq(RegField.r(width, queue.io.count)),\n    )\n  }\n}\n\n/**\n  * TLDspBlock specialization of WriteQueue\n  * @param depth number of entries in the queue\n  * @param csrAddress address range for peripheral\n  * @param beatBytes beatBytes of TL interface\n  * @param p\n  */\nclass TLWriteQueue (depth: Int, csrAddress: AddressSet, beatBytes: Int)\n(implicit p: Parameters) extends WriteQueue[\n  TLClientPortParameters, TLManagerPortParameters, TLEdgeOut, TLEdgeIn, TLBundle\n](depth) with TLHasCSR {\n  val devname = \"tlQueueIn\"\n  val devcompat = Seq(\"ucb-art\", \"dsptools\")\n  val device = new SimpleDevice(devname, devcompat) {\n    override def describe(resources: ResourceBindings): Description = {\n      val Description(name, mapping) = super.describe(resources)\n      Description(name, mapping)\n    }\n  }\n  // make diplomatic TL node for regmap\n  override val mem = Some(TLRegisterNode(address = Seq(csrAddress), device = device, beatBytes = beatBytes))\n}\n\nobject TLWriteQueue {\n  def apply(\n    depth: Int = 8,\n    csrAddress: AddressSet = AddressSet(0x2000, 0xff),\n    beatBytes: Int = 8,\n  )(implicit p: Parameters) = {\n    val writeQueue = LazyModule(new TLWriteQueue(depth = depth, csrAddress = csrAddress, beatBytes = beatBytes))\n    writeQueue\n  }\n}\n\n/**\n  * The streaming interface adds elements into the queue.\n  * The memory interface can read elements out of the queue.\n  * @param depth number of entries in the queue\n  * @param streamParameters parameters for the stream node\n  * @param p\n  */\nabstract class ReadQueue[D, U, E, O, B <: Data]\n(\n  val depth: Int,\n  val streamParameters: AXI4StreamSlaveParameters = AXI4StreamSlaveParameters()\n)(implicit p: Parameters) extends DspBlock[D, U, E, O, B] with HasCSR {\n  val streamNode = AXI4StreamSlaveNode(streamParameters)\n\n  lazy val module = new LazyModuleImp(this) {\n    require(streamNode.in.length == 1)\n\n    // get the input associated with the stream node\n    val in = streamNode.in.head._1\n    // make a Decoupled[UInt] that RegReadFn can do something with\n    val out = Wire(Decoupled(UInt()))\n    // get width of streaming input interface\n    val width = in.params.n * 8\n    // instantiate a queue\n    val queue = Module(new Queue(UInt(in.params.dataBits.W), depth))\n    // connect input to the streaming interface\n    queue.io.enq.valid := in.valid\n    queue.io.enq.bits := in.bits.data\n    in.ready := queue.io.enq.ready\n    // connect output to wire\n    out.valid := queue.io.deq.valid\n    out.bits := queue.io.deq.bits\n    queue.io.deq.ready := out.ready\n\n    regmap(\n      // map the output of the queue\n      0x0         -> Seq(RegField.r(width, RegReadFn(out))),\n      // read the number of elements in the queue\n      (width+7)/8 -> Seq(RegField.r(width, queue.io.count)),\n    )\n  }\n}\n\n/**\n  * TLDspBlock specialization of ReadQueue\n  * @param depth number of entries in the queue\n  * @param csrAddress address range\n  * @param beatBytes beatBytes of TL interface\n  * @param p\n  */\nclass TLReadQueue( depth: Int, csrAddress: AddressSet, beatBytes: Int)\n(implicit p: Parameters) extends ReadQueue[\n  TLClientPortParameters, TLManagerPortParameters, TLEdgeOut, TLEdgeIn, TLBundle\n](depth) with TLHasCSR {\n  val devname = \"tlQueueOut\"\n  val devcompat = Seq(\"ucb-art\", \"dsptools\")\n  val device = new SimpleDevice(devname, devcompat) {\n    override def describe(resources: ResourceBindings): Description = {\n      val Description(name, mapping) = super.describe(resources)\n      Description(name, mapping)\n    }\n  }\n  // make diplomatic TL node for regmap\n  override val mem = Some(TLRegisterNode(address = Seq(csrAddress), device = device, beatBytes = beatBytes))\n}\n\nobject TLReadQueue {\n  def apply(\n    depth: Int = 8,\n    csrAddress: AddressSet = AddressSet(0x2100, 0xff),\n    beatBytes: Int = 8)(implicit p: Parameters) = {\n    val readQueue = LazyModule(new TLReadQueue(depth = depth, csrAddress = csrAddress, beatBytes = beatBytes))\n    readQueue\n  }\n}\n","chipyard:generators/chipyard/src/main/scala/example/dsptools/GenericFIR.scala":"//// See LICENSE for license details.\n//\npackage chipyard.example\n\nimport chisel3._\nimport chisel3.util._\nimport dspblocks._\nimport dsptools.numbers._\nimport freechips.rocketchip.amba.axi4stream._\nimport org.chipsalliance.cde.config.{Parameters, Field, Config}\nimport freechips.rocketchip.diplomacy._\nimport freechips.rocketchip.tilelink._\nimport freechips.rocketchip.subsystem._\nimport fixedpoint._\nimport fixedpoint.{fromIntToBinaryPoint, fromSIntToFixedPoint, fromUIntToFixedPoint}\n\n// FIR params\ncase class GenericFIRParams(\n  writeAddress: BigInt = 0x2000,\n  readAddress: BigInt = 0x2100,\n  depth: Int\n)\n\ncase object GenericFIRKey extends Field[Option[GenericFIRParams]](None)\n\nclass GenericFIRCellBundle[T<:Data:Ring](genIn:T, genOut:T) extends Bundle {\n  val data: T = genIn.cloneType\n  val carry: T = genOut.cloneType\n}\nobject GenericFIRCellBundle {\n  def apply[T<:Data:Ring](genIn:T, genOut:T): GenericFIRCellBundle[T] = new GenericFIRCellBundle(genIn, genOut)\n}\n\nclass GenericFIRCellIO[T<:Data:Ring](genIn:T, genOut:T) extends Bundle {\n  val coeff = Input(genIn.cloneType)\n  val in = Flipped(Decoupled(GenericFIRCellBundle(genIn, genOut)))\n  val out = Decoupled(GenericFIRCellBundle(genIn, genOut))\n}\nobject GenericFIRCellIO {\n  def apply[T<:Data:Ring](genIn:T, genOut:T): GenericFIRCellIO[T] = new GenericFIRCellIO(genIn, genOut)\n}\n\nclass GenericFIRBundle[T<:Data:Ring](proto: T) extends Bundle {\n  val data: T = proto.cloneType\n}\nobject GenericFIRBundle {\n  def apply[T<:Data:Ring](proto: T): GenericFIRBundle[T] = new GenericFIRBundle(proto)\n}\n\nclass GenericFIRIO[T<:Data:Ring](genIn:T, genOut:T) extends Bundle {\n  val in = Flipped(Decoupled(GenericFIRBundle(genIn)))\n  val out = Decoupled(GenericFIRBundle(genOut))\n}\nobject GenericFIRIO {\n  def apply[T<:Data:Ring](genIn:T, genOut:T): GenericFIRIO[T] = new GenericFIRIO(genIn, genOut)\n}\n\n// A generic FIR filter\n// DOC include start: GenericFIR chisel\nclass GenericFIR[T<:Data:Ring](genIn:T, genOut:T, coeffs: => Seq[T]) extends Module {\n  val io = IO(GenericFIRIO(genIn, genOut))\n\n  // Construct a vector of genericFIRDirectCells\n  val directCells = Seq.fill(coeffs.length){ Module(new GenericFIRDirectCell(genIn, genOut)).io }\n\n  // Construct the direct FIR chain\n  for ((cell, coeff) <- directCells.zip(coeffs)) {\n    cell.coeff := coeff\n  }\n\n  // Connect input to first cell\n  directCells.head.in.bits.data := io.in.bits.data\n  directCells.head.in.bits.carry := Ring[T].zero\n  directCells.head.in.valid := io.in.valid\n  io.in.ready := directCells.head.in.ready\n\n  // Connect adjacent cells\n  // Note that .tail() returns a collection that consists of all\n  // elements in the inital collection minus the first one.\n  // This means that we zip together directCells[0, n] and\n  // directCells[1, n]. However, since zip ignores unmatched elements,\n  // the resulting zip is (directCells[0], directCells[1]) ...\n  // (directCells[n-1], directCells[n])\n  for ((current, next) <- directCells.zip(directCells.tail)) {\n    next.in.bits := current.out.bits\n    next.in.valid := current.out.valid\n    current.out.ready := next.in.ready\n  }\n\n  // Connect output to last cell\n  io.out.bits.data := directCells.last.out.bits.carry\n  directCells.last.out.ready := io.out.ready\n  io.out.valid := directCells.last.out.valid\n\n}\n// DOC include end: GenericFIR chisel\n\n// A generic FIR direct cell used to construct a larger direct FIR chain\n//\n//   in ----- [z^-1]-- out\n//\t        |\n//   coeff ----[*]\n//\t        |\n//   carryIn --[+]-- carryOut\n//\n// DOC include start: GenericFIRDirectCell chisel\nclass GenericFIRDirectCell[T<:Data:Ring](genIn: T, genOut: T) extends Module {\n  val io = IO(GenericFIRCellIO(genIn, genOut))\n\n  // Registers to delay the input and the valid to propagate with calculations\n  val hasNewData = RegInit(0.U)\n  val inputReg = Reg(genIn.cloneType)\n\n  // Passthrough ready\n  io.in.ready := io.out.ready\n\n  // When a new transaction is ready on the input, we will have new data to output\n  // next cycle. Take this data in\n  when (io.in.fire) {\n    hasNewData := 1.U\n    inputReg := io.in.bits.data\n  }\n\n  // We should output data when our cell has new data to output and is ready to\n  // recieve new data. This insures that every cell in the chain passes its data\n  // on at the same time\n  io.out.valid := hasNewData & io.in.fire\n  io.out.bits.data := inputReg\n\n  // Compute carry\n  // This uses the ring implementation for + and *, i.e.\n  // (a * b) maps to (Ring[T].prod(a, b)) for whicever T you use\n  io.out.bits.carry := inputReg * io.coeff + io.in.bits.carry\n}\n// DOC include end: GenericFIRDirectCell chisel\n\n\n// DOC include start: GenericFIRBlock chisel\nabstract class GenericFIRBlock[D, U, EO, EI, B<:Data, T<:Data:Ring]\n(\n  genIn: T,\n  genOut: T,\n  coeffs: => Seq[T]\n)(implicit p: Parameters) extends DspBlock[D, U, EO, EI, B] {\n  val streamNode = AXI4StreamIdentityNode()\n  val mem = None\n\n  lazy val module = new LazyModuleImp(this) {\n    require(streamNode.in.length == 1)\n    require(streamNode.out.length == 1)\n\n    val in = streamNode.in.head._1\n    val out = streamNode.out.head._1\n\n    // instantiate generic fir\n    val fir = Module(new GenericFIR(genIn, genOut, coeffs))\n\n    // Attach ready and valid to outside interface\n    in.ready := fir.io.in.ready\n    fir.io.in.valid := in.valid\n\n    fir.io.out.ready := out.ready\n    out.valid := fir.io.out.valid\n\n    // cast UInt to T\n    fir.io.in.bits := in.bits.data.asTypeOf(GenericFIRBundle(genIn))\n\n    // cast T to UInt\n    out.bits.data := fir.io.out.bits.asUInt\n  }\n}\n// DOC include end: GenericFIRBlock chisel\n\n// DOC include start: TLGenericFIRBlock chisel\nclass TLGenericFIRBlock[T<:Data:Ring]\n(\n  val genIn: T,\n  val genOut: T,\n  coeffs: => Seq[T]\n)(implicit p: Parameters) extends\nGenericFIRBlock[TLClientPortParameters, TLManagerPortParameters, TLEdgeOut, TLEdgeIn, TLBundle, T](\n    genIn, genOut, coeffs\n) with TLDspBlock\n// DOC include end: TLGenericFIRBlock chisel\n\n// DOC include start: TLGenericFIRChain chisel\nclass TLGenericFIRChain[T<:Data:Ring] (genIn: T, genOut: T, coeffs: => Seq[T], params: GenericFIRParams)(implicit p: Parameters)\n  extends TLChain(Seq(\n    TLWriteQueue(params.depth, AddressSet(params.writeAddress, 0xff))(_),\n    { implicit p: Parameters =>\n      val fir = LazyModule(new TLGenericFIRBlock(genIn, genOut, coeffs))\n      fir\n    },\n    TLReadQueue(params.depth, AddressSet(params.readAddress, 0xff))(_)\n  ))\n// DOC include end: TLGenericFIRChain chisel\n\n// DOC include start: CanHavePeripheryStreamingFIR chisel\ntrait CanHavePeripheryStreamingFIR extends BaseSubsystem {\n  val streamingFIR = p(GenericFIRKey) match {\n    case Some(params) => {\n      val pbus = locateTLBusWrapper(PBUS)\n      val domain = pbus.generateSynchronousDomain.suggestName(\"fir_domain\")\n      val streamingFIR = domain { LazyModule(new TLGenericFIRChain(\n        genIn = FixedPoint(8.W, 3.BP),\n        genOut = FixedPoint(8.W, 3.BP),\n        coeffs = Seq(1.U.asFixedPoint(0.BP), 2.U.asFixedPoint(0.BP), 3.U.asFixedPoint(0.BP)),\n        params = params)) }\n      pbus.coupleTo(\"streamingFIR\") { domain { streamingFIR.mem.get := TLFIFOFixer() := TLFragmenter(pbus.beatBytes, pbus.blockBytes) } := _ }\n      Some(streamingFIR)\n    }\n    case None => None\n  }\n}\n// DOC include end: CanHavePeripheryStreamingFIR chisel\n\n/**\n * Mixin to add FIR to rocket config\n */\n// DOC include start: WithStreamingFIR\nclass WithStreamingFIR extends Config((site, here, up) => {\n  case GenericFIRKey => Some(GenericFIRParams(depth = 8))\n})\n// DOC include end: WithStreamingFIR\n","chipyard:generators/chipyard/src/main/scala/example/dsptools/StreamingPassthrough.scala":"//// See LICENSE for license details.\n//\npackage chipyard.example\n\nimport chisel3._\nimport chisel3.{Bundle, Module}\nimport chisel3.util._\nimport dspblocks._\nimport dsptools.numbers._\nimport freechips.rocketchip.amba.axi4stream._\nimport org.chipsalliance.cde.config.{Parameters, Field, Config}\nimport freechips.rocketchip.diplomacy._\nimport freechips.rocketchip.tilelink._\nimport freechips.rocketchip.subsystem._\n\n// Simple passthrough to use as testbed sanity check\n// StreamingPassthrough params\ncase class StreamingPassthroughParams(\n  writeAddress: BigInt = 0x2200,\n  readAddress: BigInt = 0x2300,\n  depth: Int\n)\n\n// StreamingPassthrough key\ncase object StreamingPassthroughKey extends Field[Option[StreamingPassthroughParams]](None)\n\nclass StreamingPassthroughBundle[T<:Data:Ring](proto: T) extends Bundle {\n    val data: T = proto.cloneType\n}\nobject StreamingPassthroughBundle {\n    def apply[T<:Data:Ring](proto: T): StreamingPassthroughBundle[T] = new StreamingPassthroughBundle(proto)\n}\n\nclass StreamingPassthroughIO[T<:Data:Ring](proto: T) extends Bundle {\n    val in = Flipped(Decoupled(StreamingPassthroughBundle(proto)))\n    val out = Decoupled(StreamingPassthroughBundle(proto))\n}\nobject StreamingPassthroughIO {\n    def apply[T<:Data:Ring](proto: T): StreamingPassthroughIO[T] = new StreamingPassthroughIO(proto)\n}\n\nclass StreamingPassthrough[T<:Data:Ring](proto: T) extends Module {\n    val io = IO(StreamingPassthroughIO(proto))\n\n    io.in.ready := io.out.ready\n    io.out.bits.data := io.in.bits.data\n    io.out.valid := io.in.valid\n}\n\n/**\n  * Make DspBlock wrapper for StreamingPassthrough\n  * @param cordicParams parameters for cordic\n  * @param ev$1\n  * @param ev$2\n  * @param ev$3\n  * @param p\n  * @tparam D\n  * @tparam U\n  * @tparam EO\n  * @tparam EI\n  * @tparam B\n  * @tparam T Type parameter for passthrough, i.e. FixedPoint or DspReal\n  */\nabstract class StreamingPassthroughBlock[D, U, EO, EI, B<:Data, T<:Data:Ring]\n(\n  proto: T\n)(implicit p: Parameters) extends DspBlock[D, U, EO, EI, B] {\n  val streamNode = AXI4StreamIdentityNode()\n  val mem = None\n\n  lazy val module = new LazyModuleImp(this) {\n    require(streamNode.in.length == 1)\n    require(streamNode.out.length == 1)\n\n    val in = streamNode.in.head._1\n    val out = streamNode.out.head._1\n\n    // instantiate passthrough\n    val passthrough = Module(new StreamingPassthrough(proto))\n\n    // Pass ready and valid from read queue to write queue\n    in.ready := passthrough.io.in.ready\n    passthrough.io.in.valid := in.valid\n\n    // cast UInt to T\n    passthrough.io.in.bits := in.bits.data.asTypeOf(StreamingPassthroughBundle(proto))\n\n    passthrough.io.out.ready := out.ready\n    out.valid := passthrough.io.out.valid\n\n    // cast T to UInt\n    out.bits.data := passthrough.io.out.bits.asUInt\n  }\n}\n\n/**\n  * TLDspBlock specialization of StreamingPassthrough\n  * @param cordicParams parameters for passthrough\n  * @param ev$1\n  * @param ev$2\n  * @param ev$3\n  * @param p\n  * @tparam T Type parameter for passthrough data type\n  */\nclass TLStreamingPassthroughBlock[T<:Data:Ring]\n(\n  val proto: T\n)(implicit p: Parameters) extends\nStreamingPassthroughBlock[TLClientPortParameters, TLManagerPortParameters, TLEdgeOut, TLEdgeIn, TLBundle, T](proto)\nwith TLDspBlock\n\n/**\n  * A chain of queues acting as our MMIOs with the passthrough module in between them.\n  * @param depth depth of queues\n  * @param ev$1\n  * @param ev$2\n  * @param ev$3\n  * @param p\n  * @tparam T Type parameter for passthrough, i.e. FixedPoint or DspReal\n  */\nclass TLStreamingPassthroughChain[T<:Data:Ring](params: StreamingPassthroughParams, proto: T)(implicit p: Parameters)\n  extends TLChain(Seq(\n    TLWriteQueue(params.depth, AddressSet(params.writeAddress, 0xff))(_),\n    { implicit p: Parameters => {\n      val streamingPassthrough = LazyModule(new TLStreamingPassthroughBlock(proto))\n      streamingPassthrough\n    }},\n    TLReadQueue(params.depth, AddressSet(params.readAddress, 0xff))(_)\n  ))\n\ntrait CanHavePeripheryStreamingPassthrough { this: BaseSubsystem =>\n  val passthrough = p(StreamingPassthroughKey) match {\n    case Some(params) => {\n      val pbus = locateTLBusWrapper(PBUS)\n      val domain = pbus.generateSynchronousDomain.suggestName(\"streaming_passthrough_domain\")\n      val streamingPassthroughChain = domain { LazyModule(new TLStreamingPassthroughChain(params, UInt(32.W))) }\n      pbus.coupleTo(\"streamingPassthrough\") { domain { streamingPassthroughChain.mem.get := TLFIFOFixer() := TLFragmenter(pbus.beatBytes, pbus.blockBytes)} := _ }\n      Some(streamingPassthroughChain)\n    }\n    case None => None\n  }\n}\n\n/**\n * Mixin to add passthrough to rocket config\n */\nclass WithStreamingPassthrough extends Config((site, here, up) => {\n  case StreamingPassthroughKey => Some(StreamingPassthroughParams(depth = 8))\n})\n","chipyard:generators/chipyard/src/main/scala/harness/HarnessBinders.scala":"package chipyard.harness\n\nimport chisel3._\nimport chisel3.util._\nimport chisel3.reflect.DataMirror\nimport chisel3.experimental.Direction\n\nimport org.chipsalliance.cde.config.{Field, Config, Parameters}\nimport freechips.rocketchip.diplomacy.{LazyModule, LazyModuleImpLike}\nimport freechips.rocketchip.system.{SimAXIMem}\nimport freechips.rocketchip.subsystem._\nimport freechips.rocketchip.util._\nimport freechips.rocketchip.jtag.{JTAGIO}\nimport freechips.rocketchip.devices.debug.{SimJTAG}\nimport chipyard.iocell._\nimport testchipip.dram.{SimDRAM}\nimport testchipip.tsi.{SimTSI, SerialRAM, TSI, TSIIO}\nimport testchipip.soc.{TestchipSimDTM}\nimport testchipip.spi.{SimSPIFlashModel}\nimport testchipip.uart.{UARTAdapter, UARTToSerial}\nimport testchipip.serdes._\nimport testchipip.iceblk.{SimBlockDevice, BlockDeviceModel}\nimport testchipip.cosim.{SpikeCosim}\nimport icenet.{NicLoopback, SimNetwork}\nimport chipyard._\nimport chipyard.clocking.{HasChipyardPRCI}\nimport chipyard.iobinders._\n\ncase object HarnessBinders extends Field[HarnessBinderFunction]({case _ => })\n\nobject ApplyHarnessBinders {\n  def apply(th: HasHarnessInstantiators, ports: Seq[Port[_]], chipId: Int)(implicit p: Parameters): Unit = {\n    ports.foreach(port => p(HarnessBinders)(th, port, chipId))\n  }\n}\n\nclass HarnessBinder[T <: HasHarnessInstantiators, S <: Port[_]](\n  fn: => HarnessBinderFunction\n) extends Config((site, here, up) => {\n  case HarnessBinders => fn orElse up(HarnessBinders)\n})\n\n\nclass WithGPIOTiedOff extends HarnessBinder({\n  case (th: HasHarnessInstantiators, port: GPIOPort, chipId: Int) => {\n    port.io <> AnalogConst(0)\n\n  }\n})\n\nclass WithGPIOPinsTiedOff extends HarnessBinder({\n  case (th: HasHarnessInstantiators, port: GPIOPinsPort, chipId: Int) => {\n    port.io := DontCare\n\n  }\n})\n\n// DOC include start: WithUARTAdapter\nclass WithUARTAdapter extends HarnessBinder({\n  case (th: HasHarnessInstantiators, port: UARTPort, chipId: Int) => {\n    val div = (th.getHarnessBinderClockFreqMHz.toDouble * 1000000 / port.io.c.initBaudRate.toDouble).toInt\n    UARTAdapter.connect(Seq(port.io), div, false)\n  }\n})\n// DOC include end: WithUARTAdapter\n\nclass WithSimSPIFlashModel(rdOnly: Boolean = true) extends HarnessBinder({\n  case (th: HasHarnessInstantiators, port: SPIFlashPort, chipId: Int) => {\n    val spi_mem = Module(new SimSPIFlashModel(port.params.fSize, port.spiId, rdOnly)).suggestName(s\"spi_mem${port.spiId}\")\n    spi_mem.io.sck := port.io.sck\n    require(port.params.csWidth == 1, \"I don't know what to do with your extra CS bits. Fix me please.\")\n    spi_mem.io.cs(0) := port.io.cs(0)\n    spi_mem.io.dq.zip(port.io.dq).foreach { case (x, y) => x <> y }\n    spi_mem.io.reset := th.harnessBinderReset\n  }\n})\n\nclass WithI2